/* PR is the Citrus Projections 2.0 roster for opening night, 29 September
   against Montreal. Every live game on this page settles against a game
   played on 12 March, so nothing here builds a pool out of it any more.
   It survives for the one place a September projection belongs: the
   "Projected tonight" card on a player's own page.                     */
const SC = {g:3, a:2, ppp:1, sog:.4, blk:.5, hit:.2, pim:.5, tk:1};
/* Citrus Projections 2.0 does not carry takeaways, so the rate here is the
   plain one: this season's takeaways over this season's games, out of the
   same roster file every other season number on this page comes from. It is
   labelled as a season rate wherever it is shown, never as a projection. */
(function(){
  const rate = {};
  PD.roster.forEach(p => { if (p.gp) rate[p.n] = +(p.tk / p.gp).toFixed(2); });
  PR.forEach(p => { p.tk = rate[p.name] != null ? rate[p.name] : 0; });
})();
const byFp    = [...SK].sort((a,b) => b.fpts - a.fpts);
const BEST_SK = byFp[0];

const $  = s => document.querySelector(s);
const el = (t,c,h) => { const n=document.createElement(t); if(c)n.className=c; if(h!=null)n.innerHTML=h; return n; };
const last = n => n.split(' ').pop();
const shuffle = a => [...a].sort(() => Math.random()-.5);
const rand = a => a[Math.floor(Math.random()*a.length)];

/* ── POINTS ECONOMY ──────────────────────────────────────────────
   One number across every game. This is the retention mechanic: a fan
   has a single score that only goes up by coming back. Per-game boards
   still exist, but the fanbase ranks on CP.                        */
let CP = 0;
const CP_LOG = [];
const CALM = matchMedia('(prefers-reduced-motion: reduce)').matches;

/* ══ THE FEEL ENGINE ══════════════════════════════════════════════
   Numbers from MOTION-SPEC.md: desktop moves 150-250ms, hitstop 70ms,
   shake rare and <=1.2deg, particles only for top-tier wins, synth
   audio detuned +-4% so repeats sound alive. */

// ── sound: WebAudio, zero assets, gesture-gated, one mute ──────────
const Snd = (() => {
  let ctx = null, on = true;
  const ac = () => {
    if (!on) return null;
    if (!ctx) { try { ctx = new (window.AudioContext || window.webkitAudioContext)(); } catch(e){ return null; } }
    if (ctx.state === 'suspended') ctx.resume();
    return ctx;
  };
  const det = f => f * (1 + (Math.random() * 0.08 - 0.04));
  function tone(freq, dur, type, gain, when){
    const c = ac(); if (!c) return;
    const t0 = c.currentTime + (when || 0);
    const o = c.createOscillator(), g = c.createGain();
    o.type = type; o.frequency.setValueAtTime(det(freq), t0);
    g.gain.setValueAtTime(0, t0);
    g.gain.linearRampToValueAtTime(gain, t0 + 0.012);
    g.gain.exponentialRampToValueAtTime(0.0004, t0 + dur);
    o.connect(g).connect(c.destination);
    o.start(t0); o.stop(t0 + dur + 0.03);
  }
  return {
    toggle(){ on = !on; return on; },
    get on(){ return on; },
    tick(step){ tone(880 + (step||0)*16, 0.07, 'triangle', 0.10); },
    pick(){ tone(620, 0.06, 'triangle', 0.09); },
    ding(){ tone(660, 0.09, 'triangle', 0.11); tone(990, 0.12, 'triangle', 0.10, 0.07); },
    thud(){ tone(150, 0.13, 'sine', 0.14); },
    win(){ [523, 659, 784, 1047].forEach((f,i) => tone(f, 0.09, 'triangle', 0.11, i*0.07)); },
    reveal(){ tone(440, 0.05, 'triangle', 0.06); },
  };
})();
$('#sndBtn').onclick = () => {
  const on = Snd.toggle();
  $('#sndBtn').classList.toggle('off', !on);
  $('#sndBtn').setAttribute('aria-label', on ? 'Sound on' : 'Sound off');
  if (on) Snd.tick();
};

// ── hitstop: a 70ms freeze before bad news lands ───────────────────
function hitstop(fn){ CALM ? fn() : setTimeout(fn, 75); }

// ── shake: reserved for streak-breaking misses ─────────────────────
function shakeCard(el){
  if (CALM || !el) return;
  el.classList.remove('cardshake'); void el.offsetWidth; el.classList.add('cardshake');
}

// ── confetti: 16 pieces, up-bias, top-tier wins ONLY ───────────────
const CONF_C = ['#FFC43D','#FF8A3D','#8FBEF0','#A4D65E','#FFFFFF'];
function confetti(x, y){
  if (CALM) return;
  const px = x != null ? x : innerWidth/2, py = y != null ? y : innerHeight/3;
  for (let i = 0; i < 16; i++){
    const p = el('div','confp');
    p.style.left = px+'px'; p.style.top = py+'px';
    p.style.background = CONF_C[i % CONF_C.length];
    const ang = (Math.PI*2*i)/16 + Math.random()*0.6;
    const dist = 90 * (0.45 + Math.random()*0.55);
    const dx = Math.cos(ang)*dist, dy = Math.sin(ang)*dist - 34;
    const life = 550 + Math.random()*400;
    p.animate([
      { transform:'translate(0,0) rotate(0)', opacity:1 },
      { transform:'translate('+dx+'px,'+(dy+130)+'px) rotate('+(Math.random()*540-270)+'deg)', opacity:0 }
    ], { duration: life, easing:'cubic-bezier(.22,1,.36,1)' });
    document.body.appendChild(p);
    setTimeout(() => p.remove(), life);
  }
}

// ── floaters: +15 / −5 born at the click ───────────────────────────
function floater(text, good){
  if (CALM) return;
  const from = window.__lastClick || {x: innerWidth/2, y: innerHeight/2};
  const f = el('div','floatpt', text);
  f.style.left = from.x+'px'; f.style.top = (from.y-14)+'px';
  f.style.color = good ? 'var(--good)' : 'var(--bad)';
  document.body.appendChild(f);
  requestAnimationFrame(() => { f.style.transform = 'translateY(-46px)'; f.style.opacity = '0'; });
  setTimeout(() => f.remove(), 850);
}

// ── rolling numbers: any element counts to a value ─────────────────
function rollNum(elm, to, dec, ms){
  if (!elm) return;
  if (CALM){ elm.textContent = dec ? to.toFixed(dec) : Math.round(to).toLocaleString(); return; }
  const t0 = performance.now(), dur = ms || 480;
  const step = t => {
    const k = Math.min(1, (t-t0)/dur), e = 1 - Math.pow(1-k, 3), v = to * e;
    elm.textContent = dec ? v.toFixed(dec) : Math.round(v).toLocaleString();
    if (k < 1) requestAnimationFrame(step);
  };
  requestAnimationFrame(step);
}

/* points fly from where they were earned to the counter, and the counter
   counts up instead of teleporting. Feel is mostly this function. */
function flyPoints(n){
  if (CALM) return;
  const cp = document.querySelector('.cp'); if (!cp) return;
  const from = window.__lastClick || {x: innerWidth/2, y: innerHeight/2};
  const to = cp.getBoundingClientRect();
  const f = el('div','flypts','+'+n);
  f.style.left = from.x+'px'; f.style.top = from.y+'px';
  document.body.appendChild(f);
  requestAnimationFrame(()=>{
    f.style.transform = 'translate('+(to.left+to.width/2-from.x)+'px,'+(to.top+to.height/2-from.y)+'px) scale(.5)';
    f.style.opacity = '0';
  });
  setTimeout(()=>{ f.remove();
    cp.classList.remove('bump'); void cp.offsetWidth; cp.classList.add('bump'); }, 700);
}
let cpShown = 0;
function countUp(){
  if (CALM){ $('#cpTotal').textContent = CP.toLocaleString(); cpShown = CP; return; }
  const from = cpShown, to = CP, t0 = performance.now();
  const step = t => {
    const k = Math.min(1, (t-t0)/550), e = 1-Math.pow(1-k,3);
    $('#cpTotal').textContent = Math.round(from+(to-from)*e).toLocaleString();
    if (k < 1) requestAnimationFrame(step); else cpShown = to;
  };
  requestAnimationFrame(step);
}
addEventListener('pointerdown', e => { window.__lastClick = {x:e.clientX, y:e.clientY}; }, true);

function award(n, why){
  if (n <= 0) return;
  CP += n; CP_LOG.unshift({n, why});
  // attribute to the open game so the locker-room tile can show what it paid
  const t = document.querySelector('nav .navitem[aria-selected="true"]');
  if (t && t.dataset.t !== 'home') GAME_CP[t.dataset.t] = (GAME_CP[t.dataset.t] || 0) + n;
  countUp(); flyPoints(n);
  markPlayed();
  if (typeof ROOM !== 'undefined' && ROOM.ok && ROOM.me)
    ROOM.score(CP, t && t.dataset.t !== 'home' ? t.dataset.t : null, why);
  const chip = $('#cpChip');
  chip.textContent = '+' + n;
  chip.classList.remove('pop'); void chip.offsetWidth; chip.classList.add('pop');
  drawCPLog();
}

