/* ── hero crops ───────────────────────────────────────────────────
   A focal point tuned for a 1:1 stamp is the wrong point for a 6:1
   band. The same coordinates that centred a face now sit under the
   headline. These are the band-specific crops, read off the renders. */
const HERO = {
  ult:   {fx:'62%', fy:'52%'},
  stormy:{fx:'42%', fy:'46%'},
  hl:    {fx:'70%', fy:'40%'},
  guess: {fx:'70%', fy:'38%'},
  luck:  {fx:'68%', fy:'46%'},
  rank:  {fx:'66%', fy:'44%'},
  fx:    {fx:'68%', fy:'40%'},
  bz:    {fx:'70%', fy:'38%'},
  grid:  {fx:'50%', fy:'42%'},
  lb:    {fx:'58%', fy:'46%'},
};
document.querySelectorAll('.ghero > img[data-art]').forEach(img => {
  const key = img.dataset.art, a = ART[key], h = HERO[key];
  /* ONE render beats two. A plate and a cut-out were generated separately. Different key light, different camera height, different horizon, so no
     shadow underneath was ever going to make them one picture. When a single
     composite exists for this page it replaces BOTH layers and the band is
     just that image with the copy veil over its quiet side. */
  const solo = ART['hero_'+key];
  if (solo){
    const hero = img.closest('.ghero');
    if (hero){ hero.classList.add('plated','solo'); const t = hero.querySelector('.tint'); if (t) t.remove(); }
    img.className = 'bg plate'; img.removeAttribute('data-art'); img.src = solo.src; img.alt = '';
    return;   /* header CSS hides the plate; the avatar comes from the boxed path below */
  }
  const band = ART['band_'+key];
  if (band){
    const bg = img.cloneNode(false);
    bg.className = 'bg plate'; bg.removeAttribute('data-art'); bg.src = band.src; bg.alt = '';
    img.parentNode.insertBefore(bg, img);
    const hero = img.closest('.ghero');
    if (hero){ hero.classList.add('plated'); const t = hero.querySelector('.tint'); if (t) t.remove(); }
    if (a){
      /* a cut-out has no room of its own, so it composites onto the plate
         instead of sitting on it in a box. Falls back to the boxed render. */
      const CUT = {ult:'cut_ult', hl:'cut_lemon', rank:'cut_lemon', fx:'cut_lemon', lb:'cut_lemon',
                   guess:'cut_kiwi', luck:'cut_kiwi', bz:'cut_pineapple', stormy:'cut_stormy'};
      const cut = ART[CUT[key]];
      img.classList.add('fg'); img.removeAttribute('data-art');
      img.style.setProperty('--afx', a.fx); img.style.setProperty('--afy', a.fy);
      img.style.setProperty('--az', a.z || 1.6);
      const hav = el('span','hav');
      if (cut){ img.src = cut.src; img.classList.add('cut'); hav.classList.add('cutout'); }
      img.parentNode.insertBefore(hav, img); hav.appendChild(img);
      return;
    }
    img.remove(); return;
  }
  if (!a){
    /* no render for this one yet -- the grid's identity is the board itself,
       so it gets a drawn motif rather than an empty band or a borrowed cast
       member standing in for a game he is not in. */
    const m = el('div','motif');
    m.innerHTML = '<svg viewBox="0 0 120 120" aria-hidden="true">'+
      [0,1,2].map(r=>[0,1,2].map(c=>
        '<rect x="'+(8+c*38)+'" y="'+(8+r*38)+'" width="30" height="30" rx="7"/>').join('')).join('')+
      '</svg>';
    img.replaceWith(m); return;
  }
  if (h){ img.style.setProperty('--fx', h.fx); img.style.setProperty('--fy', h.fy); }
  img.classList.add('bg');
  const fg = img.cloneNode(false);
  fg.className = 'fg'; fg.removeAttribute('data-art'); fg.alt = '';
  /* the band focal is tuned for a 6:1 crop; a 44px square avatar wants the
     face, which is what the ART map has always carried for the rail thumbs */
  fg.style.setProperty('--afx', a.fx); fg.style.setProperty('--afy', a.fy);
  fg.style.setProperty('--az', a.z || 1.6);
  /* wrapped, because a zoom-to-face crop needs a box to be clipped by --
     the same wrapper-plus-transform the rail thumbs have always used. In the
     mascot skin the wrapper is display:contents and changes nothing. */
  const hav = el('span','hav');
  hav.appendChild(fg);
  img.parentNode.insertBefore(hav, img.nextSibling);
});

/* ── the rail ─────────────────────────────────────────────────────── */
/* the grid has no mascot on purpose. A nine-square glyph says what the game
   is faster than any character could, and it costs nothing to ship. */
const GRID_GLYPH = '<svg viewBox="0 0 24 24" aria-hidden="true" class="gg">'+
  '<rect x="3" y="3" width="18" height="18" rx="2.4"/>'+
  '<path d="M9 3v18M15 3v18M3 9h18M3 15h18"/></svg>';
const HOME_ICON = '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M3 11l9-7 9 7"/><path d="M5 10v9h14v-9"/><path d="M10 19v-5h4v5"/></svg>';
function buildRail(){
  const nav = $('nav'); nav.innerHTML = '';
  const item = (t, label, art, home) => {
    const b = el('button','navitem'+(home?' home':''));
    b.setAttribute('role','tab'); b.setAttribute('aria-selected','false');
    b.setAttribute('aria-controls','p-'+t); b.dataset.t = t;
    b.title = label;
    const tile = el('div','tile');
    if (home) tile.innerHTML = HOME_ICON;
    else if (art === 'grid') { b.classList.add('home'); tile.innerHTML = GRID_GLYPH; }
    else { const i = el('img'); i.src = ART[art].src; i.alt = ''; setArt(i, ART[art]); tile.appendChild(i); }
    b.appendChild(tile); b.appendChild(el('span','lab', label));
    b.onclick = () => go(t);
    nav.appendChild(b);
    return b;
  };
  item('home','Locker room',null,true);
  GAMES.forEach(g => item(g.t, g.short, g.t));
  item(DASH.t, DASH.short, DASH.art);
  item(BOARD.t, BOARD.short, BOARD.t);
}
/* ── strips that scroll sideways say so ───────────────────────────
   Three of them in this build, and not one of them looked scrollable:
   the thirteen game tabs (1436px of them, so eight of the ten games were
   behind an invisible gesture at every width), the roster rail on a
   player page, and that page's four section tabs. All three hide the
   scrollbar, which is right, and none of them replaced it, which is not.

   A fade appears on whichever side still has something parked on it, off
   the real scroll position so it can never point at nothing, and on a
   pointer device the tabs also get a chevron, because a mouse has no
   swipe. On a phone the chevrons stay off: a thumb already knows how to
   swipe and two 30px buttons would eat a tab and a half of a 346px
   strip.                                                              */
const HINTED = [];
function hintScroll(node, wrapCls){
  if (!node || node.__hinted) return;
  node.__hinted = 1;
  let w = node.parentElement;
  if (!w || !w.classList.contains('hscroll')){
    w = el('div', 'hscroll' + (wrapCls ? ' ' + wrapCls : ''));
    node.parentNode.insertBefore(w, node);
    w.appendChild(node);
  }
  const upd = () => {
    const max = node.scrollWidth - node.clientWidth;
    w.classList.toggle('canl', max > 2 && node.scrollLeft > 2);
    w.classList.toggle('canr', max > 2 && node.scrollLeft < max - 2);
  };
  node.addEventListener('scroll', upd, {passive:true});
  HINTED.push(upd);
  upd();
}
/* every strip is redrawn by the game that owns it, so the state is
   recomputed on a resize and on every panel change rather than trusting
   a width measured before the list existed */
function hintAll(){ HINTED.forEach(f => f()); }
addEventListener('resize', hintAll);

function wireNavScroll(){
  const w = document.querySelector('.navwrap'), n = $('nav');
  if (!w || !n) return;
  hintScroll(n);
  w.querySelectorAll('.navarrow').forEach(b => {
    /* three quarters of a screen, so the tab you were reading stays on
       screen as an anchor instead of the strip jumping past it */
    b.onclick = () => n.scrollBy({left:(b.dataset.d === 'l' ? -1 : 1) *
      Math.max(160, Math.round(n.clientWidth * .74)), behavior:'smooth'});
  });
}
function markPlayed(){
  document.querySelectorAll('nav .navitem').forEach(b =>
    b.querySelector('.tile').classList.toggle('played', !!GAME_CP[b.dataset.t]));
}
/* Deep links. A concourse screen carries a QR and it has to land on the game
   the poster is advertising, not on a menu -- one extra tap in a beer line is
   the whole difference between playing and not. #grid, #ult, #fx and the rest
   all resolve, and the hash follows you as you move so a link can be shared. */
const PANEL_IDS = () => [...document.querySelectorAll('.panel')].map(p => p.id.slice(2));
function routeFromHash(){
  const t = (location.hash || '').replace(/^#\/?/, '').split(/[?&/]/)[0];
  return PANEL_IDS().includes(t) ? t : null;
}
window.addEventListener('hashchange', () => { const t = routeFromHash(); if (t) go(t, true); });

let PANEL = 'home';
function go(t, fromHash){
  PANEL = t;
  if (window.__pendingGo){ clearTimeout(window.__pendingGo); window.__pendingGo = null; }
  if (!fromHash) { try { history.replaceState(null,'', t==='home' ? location.pathname : '#'+t); } catch(e){} }
  document.querySelectorAll('nav .navitem').forEach(x => {
    const on = x.dataset.t === t;
    x.setAttribute('aria-selected', on);
    if (on) x.scrollIntoView({block:'nearest', inline:'nearest'});
  });
  document.querySelectorAll('.panel').forEach(p => p.classList.remove('on'));
  const panel = $('#p-'+t); if (panel) panel.classList.add('on');
  /* .foot is also every game tile's footer -- twelve of them. The legal
     block is the one hanging directly off .wrap. */
  const foot = document.querySelector('.wrap > .foot');
  if (foot) foot.style.display = (t === 'home') ? '' : 'none';
  if (t === 'home') drawLocker();
  hintAll();
  window.scrollTo({top:0, behavior:'smooth'});
}
/* left/right arrows walk the rail, which is what a tablist owes a
   keyboard user -- the tiles are buttons, not links. */
$('nav').addEventListener('keydown', e => {
  if (e.key !== 'ArrowRight' && e.key !== 'ArrowLeft') return;
  const items = [...document.querySelectorAll('nav .navitem')];
  const i = items.indexOf(document.activeElement); if (i < 0) return;
  e.preventDefault();
  const nxt = items[(i + (e.key === 'ArrowRight' ? 1 : items.length - 1)) % items.length];
  nxt.focus(); nxt.click();
});

/* ── the locker room ──────────────────────────────────────────────── */
/* ── the locker room ──────────────────────────────────────────────
   This page used to be twelve tiles, each led by a 300px render of a
   cartoon fruit. On a phone that is a wall of cartoon before a fan
   reaches a single word of hockey, and it is the single loudest thing
   in the build saying "not a club app".

   It is now the list every sports app opens on: a row per game, the
   name, what it is, whether it is live, what it paid. The characters
   are still here, at 34px, doing the job an avatar does. They earned a
   place in the product; they had not earned the front door.          */
const LIVE_GAMES = {ult:1, hl:1, luck:1, rank:1, call:1};
function drawLocker(){
  const box = $('#lockerGrid'); if (!box) return;
  box.innerHTML = '';
  box.className = 'lockerlist';
  const row = (g, kind) => {
    const paid = GAME_CP[g.t] || 0;
    const b = el('button','lkrow' + (paid ? ' done' : ''));
    b.type = 'button';
    b.setAttribute('aria-label',
      (TITLE[g.t]||g.short) + (paid ? '. Played, ' + paid + ' points' : '. Not played yet'));
    /* A 34px crop of a wide arena plate is mud, and a 34px cartoon face is
       the thing this page was rebuilt to stop leading with. The club mark
       reads at any size and is the right thing in front of a club's own list. */
    const mark = el('span','gmark' + (g.glyph ? ' glyph' : ''));
    mark.innerHTML = g.glyph ? GRID_GLYPH : leafSVG(19, '#FFFFFF');
    b.appendChild(mark);
    const mid = el('div','gmid');
    mid.innerHTML =
      '<div class="gtop"><b>' + (TITLE[g.t]||g.short) + '</b>' +
      (LIVE_GAMES[g.t] ? '<span class="glive">LIVE</span>' : '') +
      (g.n ? '<span class="gno">Game ' + g.n + '</span>' : '') + '</div>' +
      '<p>' + g.blurb + '</p>';
    b.appendChild(mid);
    const rt = el('div','gright');
    rt.innerHTML = kind === 'board'
      ? '<b>' + CP.toLocaleString() + '</b><span>Citrus points</span>'
      : paid ? '<b class="paid">+' + paid.toLocaleString() + '</b><span>banked</span>'
             : '<b class="idle">' + (g.secs || 'open') + '</b><span>not played</span>';
    b.appendChild(rt);
    b.onclick = () => go(g.t);
    box.appendChild(b);
  };
  GAMES.forEach(g => row(g));
  row(DASH, 'dash'); row(BOARD, 'board');
}

/* ══ THE GAME CLOCK ═══════════════════════════════════════════════
   Every game in this build that says "predict" now resolves against a
   real hockey game, event by event, instead of against our own model.

   The game is Anaheim at Toronto, 12 March 2026, Scotiabank Arena.
   Toronto trails 1-3 in the second and wins 6-4. Every row below is a
   record out of nhl_shots: period, clock, shooter, coordinates,
   strength state, and the expected-goals value the shipped model gave
   that chance at the time. 106 events. Nothing invented, nothing
   reordered, nothing padded.

   Two things are true about this data and the interface says both out
   loud rather than papering over them:

     goals, assists and shots are event-level, so they tick live
     hits, blocks and takeaways exist only in the official box score,
     so they settle at the final buzzer

   That is a real constraint of real feeds, and a club will recognise
   it faster than they would recognise a number we made up.          */

