/* stats the feed can actually prove at any moment in the game */
const EVENT_K = { g:1, a:1, p:1, sog:1, att:1 };
const BOX_ONLY_NOTE = 'Hits, blocks and takeaways post at the final buzzer.';

const CLOCK = {
  t: 0, rate: 20, running: false, i: 0, over: false, held: false, subs: [], _h: null,

  on(f){ this.subs.push(f); return f; },
  emit(kind, ev){ for (const f of this.subs){ try { f(kind, ev, this); } catch(err){ console.error('CLOCK subscriber failed on ' + kind, err); } } },

  per(){ return Math.min(3, Math.floor(this.t / LIVE_G.PER) + 1); },
  left(){ return Math.max(0, this.per() * LIVE_G.PER - Math.min(this.t, LIVE_G.LEN)); },
  mmss(){ const s = this.left(); return Math.floor(s/60) + ':' + String(s%60).padStart(2,'0'); },
  label(){ return this.over ? 'Final' : ['1st','2nd','3rd'][this.per()-1] + ' ' + this.mmss(); },
  ord(){ return this.over ? 'Final' : ['1st','2nd','3rd'][this.per()-1]; },

  score(){ let h = 0, a = 0;
    for (let k = 0; k < this.i; k++){ const e = EV[k]; if (e.kind === 'G') e.home ? h++ : a++; }
    return [h, a]; },

  /* running Toronto line for a skater, from events only */
  live(name){
    const short = name.split(' ')[0][0] + '. ' + name.split(' ').slice(1).join(' ');
    const o = { g:0, a:0, p:0, sog:0, att:0 };
    for (let k = 0; k < this.i; k++){
      const e = EV[k]; if (!e.home) continue;
      if (e.sh === short){ o.att++; if (e.kind !== 'M') o.sog++; if (e.kind === 'G') o.g++; }
      if (e.kind === 'G' && (e.a1 === short || e.a2 === short)) o.a++;
    }
    o.p = o.g + o.a; return o;
  },

  /* every stat: live where the feed proves it, final where only the box does */
  now(name){
    const f = BOXF[name], l = this.live(name);
    if (!f) return l;
    return Object.assign({}, l, { hit:f.hit, blk:f.blk, pim:f.pim, tk:f.tk,
                                  toi:f.toi, shifts:f.shifts, settled:this.over });
  },

  set(r){ this.rate = r; this.emit('state'); },

  start(){ if (this.over) return; this.running = true; this.held = false;
           this.emit('state'); this._loop(); },
  pause(){ this.running = false; clearTimeout(this._h); this._h = null; this.emit('state'); },
  toggle(){ this.running ? this.pause() : this.start(); },

  hold(){ this.running = false; clearTimeout(this._h); this._h = null;
          this.held = true; this.emit('state'); },
  release(){ if (this.held){ this.held = false; this.start(); } },

  reset(){ this.pause(); this.t = 0; this.i = 0; this.over = false; this.held = false;
           this.emit('reset'); this.emit('state'); },

  /* run to the next goal, whatever the rate */
  skip(){
    for (let k = this.i; k < EV.length; k++)
      if (EV[k].kind === 'G'){ this.seek(EV[k].sec); return; }
    this.seek(LIVE_G.LEN);
  },
  seek(sec){
    while (this.i < EV.length && EV[this.i].sec <= sec){ const e = EV[this.i]; this.i++; this.emit('ev', e); }
    this.t = Math.min(sec, LIVE_G.LEN);
    if (this.t >= LIVE_G.LEN) this._final();
    this.emit('tick');
  },

  _loop(){
    if (!this.running) return;
    this._h = setTimeout(() => {
      if (!this.running) return;
      this.t = Math.min(LIVE_G.LEN, this.t + this.rate / 5);
      let fired = 0;
      while (this.i < EV.length && EV[this.i].sec <= this.t){
        const e = EV[this.i]; this.i++; fired++; this.emit('ev', e);
        if (this.held) break;
      }
      this.emit('tick');
      if (this.t >= LIVE_G.LEN){ this._final(); return; }
      if (this.held) return;
      this._loop();
    }, 200);
  },

  _final(){
    if (this.over) return;
    this.running = false; clearTimeout(this._h);
    while (this.i < EV.length){ const e = EV[this.i]; this.i++; this.emit('ev', e); }
    this.over = true; this.emit('final'); this.emit('state'); this.emit('tick');
  }
};

/* ── the score bug ────────────────────────────────────────────────
   One strip, every panel, always current. This is the single object
   that makes the whole build read as a second screen rather than a
   quiz app: the score is on screen while you are answering.        */
function bugDraw(){
  const b = $('#bug'); if (!b) return;
  const [h, a] = CLOCK.score();
  b.classList.toggle('final', CLOCK.over);
  b.classList.toggle('running', CLOCK.running);
  $('#bugH').textContent = h; $('#bugA').textContent = a;
  $('#bugClock').textContent = CLOCK.label();
  const pill = $('#bugPlay');
  if (pill) pill.textContent = CLOCK.over ? 'Replay' : CLOCK.running ? 'Pause' : (CLOCK.t ? 'Resume' : 'Start');
  const fill = $('#bugFill');
  if (fill) fill.style.width = (100 * Math.min(1, CLOCK.t / LIVE_G.LEN)).toFixed(1) + '%';
  document.querySelectorAll('.ratebtn').forEach(n =>
    n.classList.toggle('on', +n.dataset.r === CLOCK.rate));
}

function bugEvent(e){
  const b = $('#bugTick'); if (!b) return;
  if (e.kind !== 'G') return;
  const who = SHORT2FULL[e.sh] || e.sh;
  b.innerHTML = '<i class="' + (e.home ? 'tor' : 'opp') + '"></i>' +
    '<b>' + (e.home ? 'TORONTO' : 'ANAHEIM') + '</b> ' + who +
    (e.a1 ? ' <span>from ' + (SHORT2FULL[e.a1] || e.a1) + (e.a2 ? ' and ' + (SHORT2FULL[e.a2] || e.a2) : '') + '</span>' : '') +
    (e.en ? ' <em>empty net</em>' : e.str === '4v5' ? ' <em>shorthanded</em>' : e.str === '5v4' ? ' <em>power play</em>' : '');
  b.classList.remove('pop'); void b.offsetWidth; b.classList.add('pop');
  if (e.home){ Snd.win && Snd.win(); } else { Snd.thud && Snd.thud(); }
}

CLOCK.on((kind, e) => {
  if (kind === 'ev'){ bugEvent(e); return; }
  if (kind === 'reset'){ const t = $('#bugTick'); if (t) t.innerHTML = ''; }
  bugDraw();
});

/* ══ GAME 1: CREATE THE ULTIMATE LEAF ═══════════════════════════
   Runs on TONIGHT'S projections, not season totals. Every slot lists the
   skaters dressing tonight ranked by their projection in THAT category. The stick shows the goal-scorers, the shin pads show the shot-blockers.
   A Leaf can only fill one slot, so the ranked list is not the answer:
   Matthews leads goals AND shots, and taking him off the shots slot to
   put him on the stick costs 0.44 fantasy points to gain 0.15.        */
/* The sixth slot used to be penalty minutes, which is a strange thing to
   ask a fan to go shopping for when the brief is "build the best Leaf".
   It is now takeaways: the stat for the player whose feet and stick get
   there first and come away with the puck.

   Worth saying plainly, because the ask was for skating speed and this is
   not that: NHL Edge tracking (top speed, 20+ mph bursts, distance skated)
   is a separate league feed and Citrus does not ingest it. There is no
   speed column anywhere in the database. Labelling takeaways "speed" would
   be inventing a number, so the slot says takeaways and means takeaways.
   Real Edge data is an ingest job, not a demo job.                      */
const PARTS = [
  {id:'g',  part:'The stick',     cat:'Goals',     k:'g'  },
  {id:'a',  part:'The hands',     cat:'Assists',   k:'a'  },
  {id:'sog',part:'The release',   cat:'Shots',     k:'sog'},
  {id:'hit',part:'The shoulders', cat:'Hits',      k:'hit'},
  {id:'blk',part:'The shin pads', cat:'Blocks',    k:'blk'},
  {id:'tk', part:'The skates',    cat:'Takeaways', k:'tk' },
];
const val    = (p,k) => p[k] * SC[k];
const sixCat = p => PARTS.reduce((s,P) => s + val(p,P.k), 0);

/* The pool, the ceiling and the best single Leaf are all built further
   down, next to the season helper they read from. See KIT_POOL.        */

const pick = {};
let ultBanked = false, ultOpen = null;

/* ── kit art ──────────────────────────────────────────────────────
   Six props in the sticker language: flat fill, hard --deep outline,
   no gradient. These are placeholders with intent. The moment the
   rendered Citrus props land they swap in through ART.eq_<id> with
   no other change, because the tile only ever asks eqArt() for markup. */
const PART_C = {g:'--fy', a:'--fg', sog:'--fi', hit:'--fo', blk:'--ft', tk:'--fy'};
/* Monochrome silhouettes on a solid colour chip, not outlined illustrations
   floating on navy. A two-tone shape with a 6px stroke at 78px is a squiggle;
   one solid shape in --deep on a filled chip is an icon, and icons are a
   thing SVG can actually do well. The rendered props replace the glyph and
   keep the chip, so the swap is invisible to the layout. */
const EQ_SVG = {
  /* stick: long thin shaft, heel, flat blade with a tape band */
  g:'<path d="M74 8 l12 12 -40 40 -12-12z"/>'+
    '<path d="M42 52 q-16 20 -30 24 -5 1 -5 6 l1 8 q26-3 44-24z"/>'+
    '<rect x="52" y="26" width="7" height="20" transform="rotate(45 55 36)" opacity=".45"/>',
  /* glove: mitt body, thumb, cuff roll */
  a:'<path d="M32 20h26q12 0 12 12v26q0 14-14 14H38q-14 0-14-14V32q0-12 8-12z"/>'+
    '<path d="M22 40q-12 3-12 14t12 14h4V40z"/>'+
    '<path d="M22 76h52q6 0 6 6v6q0 6-6 6H22q-6 0-6-6v-6q0-6 6-6z"/>',
  /* release: puck away, wake behind */
  sog:'<circle cx="68" cy="50" r="20"/>'+
      '<rect x="10" y="28" width="26" height="8" rx="4"/>'+
      '<rect x="2" y="46" width="30" height="8" rx="4"/>'+
      '<rect x="10" y="64" width="26" height="8" rx="4"/>',
  /* shoulders: chest plate, caps proud of the line, neck notch */
  hit:'<path d="M30 32h40q7 0 8 7l6 35q1 8-7 8H23q-8 0-7-8l6-35q1-7 8-7z"/>'+
      '<path d="M28 30q-16 2-18 16 0 8 9 9l9-3z"/>'+
      '<path d="M72 30q16 2 18 16 0 8-9 9l-9-3z"/>',
  /* shin pad: knee dome, body, two wrap straps */
  blk:'<circle cx="50" cy="22" r="14"/>'+
      '<path d="M36 34h28q6 0 6 6v38q0 8-8 8H38q-8 0-8-8V40q0-6 6-6z"/>'+
      '<rect x="18" y="46" width="64" height="7" rx="3.5"/>'+
      '<rect x="18" y="64" width="64" height="7" rx="3.5"/>',
  /* skate: boot, holder, blade */
  tk:'<path d="M28 18q-10 0-10 10v28q0 7 7 8l30 5q11 2 18-6l7-8q4-5-2-8l-13-6q-6-3-7-10l-2-8q-1-5-6-5z"/>'+
      '<rect x="26" y="66" width="8" height="14" rx="3"/>'+
      '<rect x="54" y="68" width="8" height="12" rx="3"/>'+
      '<path d="M12 82h72q6 0 6 5t-6 5H12q-6 0-6-5t6-5z"/>',
};
/* Until the rendered props land the chip carries the stat itself, set in the
   display face. A letterform at 46px is always legible; an illustration at
   46px is a gamble I keep losing. It also makes the render an obvious
   upgrade rather than a sideways move, and the chip never changes size, so
   the swap is invisible to the layout. Set EQ_STYLE='glyph' to see the
   drawn silhouettes instead. */
const EQ_STYLE = 'mark';
const EQ_MARK = {g:'G', a:'A', sog:'SOG', hit:'HIT', blk:'BLK', tk:'TK'};
function eqArt(id){
  const a = (typeof ART !== 'undefined') && ART['eq_'+id];
  if (a) return '<span class="chipart"><img src="'+a.src+'" alt=""></span>';
  if (EQ_STYLE === 'glyph')
    return '<span class="chipart"><svg viewBox="0 0 100 100" aria-hidden="true">'+EQ_SVG[id]+'</svg></span>';
  /* NOT class "mark" -- that is the projection meter's tick, which is
     position:absolute, and a second collision of exactly the kind that put
     "MOST PICKED" at 2.45:1 earlier in this build. Scoped name, no collision. */
  return '<span class="chipart eqmark" data-n="'+EQ_MARK[id].length+'">'+EQ_MARK[id]+'</span>';
}

/* An earned object, shown once, big enough to feel like something.
   The badges were delivered and were sitting in the file doing nothing. */
function pinEarned(key, line){
  const a = ART[key]; if (!a || CALM) { return; }
  const w = el('div','pinwin');
  w.innerHTML = '<img src="'+a.src+'" alt=""><div><b>Unlocked</b><span>'+line+'</span></div>';
  document.body.appendChild(w);
  Snd.win();
  setTimeout(()=>{ w.classList.add('out'); setTimeout(()=>w.remove(), 420); }, 2600);
}

/* ── the characters, where they have a job ──────────────────────
   These were pulled out of the build when the page headers were rebuilt,
   and pulling them was right: a portrait in front of every one of thirteen
   titles is a wall of cartoon between a fan and the hockey.

   Putting one back is a different question, and it turns on whether the
   character is doing something. GAMES names a host for exactly four of the
   games -- Stormy the AI GM, Lemon on the Pick'em card, Pineapple in goal
   on the buzzer, Kiwi on the player pages -- and those four are the only
   places a face is a fact rather than a garnish. Stormy is the strongest of
   them by a distance: he is not a mascot on that page, he is the opponent,
   and his five sit opposite yours. */
const MASC = {stormy:'cut_stormy', lemon:'cut_lemon',
              kiwi:'cut_kiwi', pineapple:'cut_pineapple'};
function mascotImg(who, px, cls){
  const a = ART[MASC[who]];
  if (!a) return '';          /* not delivered: the page loses a face, nothing else */
  return '<span class="masc ' + (cls || '') + '" style="--mp:' + px + 'px">' +
         '<img src="' + a.src + '" alt=""></span>';
}

/* ── the Citrus mark ──────────────────────────────────────────────
   Transcribed from apps/web/src/components/citrus2/CitrusLogo.tsx, the
   on-dark variant, so the demo carries the same mark as the product
   rather than something drawn to look like it. A puck disc with the
   citrus segments inside: it reads as both.

   It brings two colours the page palette does not have, cream #FFF8F0
   and sage #84A57D. That is on purpose and it is the only exemption in
   the build: a logo owns its own colours, which is what makes it a logo.

   NOTE there are two Citrus marks in the repo and they disagree. This is
   the one the app chrome actually uses (Navbar, Auth, Waitlist, the
   footer). public/favicon.svg is an older slice on a different palette,
   #F9A436 rind and a green leaf. Worth reconciling; not here. */
function citrusMark(px){
  const seg = (x1,y1,x2,y2) => '<line x1="'+x1+'" y1="'+y1+'" x2="'+x2+'" y2="'+y2+
    '" stroke="#84A57D" stroke-width="1.5" stroke-linecap="round" opacity=".6"/>';
  return '<svg class="cmarksvg" viewBox="0 0 64 64" width="'+px+'" height="'+px+
    '" fill="none" aria-hidden="true">' +
    '<circle cx="32" cy="32" r="28" fill="#FF6B1A"/>' +
    '<circle cx="32" cy="32" r="22" fill="#FFF8F0"/>' +
    seg(32,10,32,54) + seg(10,32,54,32) + seg(16.4,16.4,47.6,47.6) + seg(47.6,16.4,16.4,47.6) +
    '<circle cx="32" cy="32" r="3" fill="#FF6B1A"/>' +
    '<circle cx="32" cy="32" r="28" fill="none" stroke="#FF6B1A" stroke-width="2" opacity=".4"/>' +
    '</svg>';
}

/* ── the leaf ─────────────────────────────────────────────────────
   A jersey badge showing a number was showing the wrong thing twice
   over: the roster data has duplicate numbers on it (22, 28, 36 and 53
   each appear on two skaters), and a number is not a mark. The badge
   now carries the Citrus leaf -- the sprig the mascots already wear --
   and the number moves down into the metadata line where a fact
   belongs. Veins survive down to about 20px and turn to mush below it,
   so the small variant drops them and keeps the midrib. */
/* ── the mark and the sweater ─────────────────────────────────────
   The leaf is the club mark; the sweater is a player's identity. Those
   are two different jobs and the build was doing both with one badge.

   Every row now carries a numbered sweater: club navy, white shoulder
   yoke, the crest on the chest and the player's number below it. It is
   the honest substitute for the headshot that Sleeper, ESPN and Yahoo
   all put on a row -- we have no photo rights, but a number on a sweater
   identifies a player to a hockey fan just as fast, and it is the club's
   own object rather than a borrowed one.

   Drop the official crest in as art/crest.png and it replaces the drawn
   leaf on the sweater and everywhere else, at every size. */
const LEAF_BODY = 'M50 3 L45 19 L35 13 L38 32 L20 26 L25 38 L4 41 L13 50 L7 58 L29 61 L24 72 L45 67 L47 96 L53 96 L55 67 L76 72 L71 61 L93 58 L87 50 L96 41 L75 38 L80 26 L62 32 L65 13 L55 19 Z';
function leafSVG(px, fill){
  if (typeof ART !== 'undefined' && ART.crest)
    return '<img class="leaf" src="'+ART.crest.src+'" alt="" width="'+px+'" height="'+px+
           '" style="object-fit:contain;display:block">';
  return '<svg class="leaf" viewBox="0 0 100 100" aria-hidden="true" width="'+px+'" height="'+px+'">'+
    '<path fill="'+(fill||'#FFFFFF')+'" d="'+LEAF_BODY+'"/></svg>';
}
/* the crest, for use inside another svg */
const crestG = (cx,cy,sc,fill) =>
  '<g transform="translate('+cx+','+cy+') scale('+sc+') translate(-50,-50)">'+
  '<path fill="'+fill+'" d="'+LEAF_BODY+'"/></g>';

/* ── the face ─────────────────────────────────────────────────────
   A club app leads with players, and a numbered sweater is the honest
   stand-in until real headshots exist rather than a stock face. Drop
   art/hs-<lastname>.png in and every row, slate and picker swaps to
   the real man automatically; anyone not delivered keeps his sweater,
   so a partial delivery is a partial upgrade and never a broken row. */
const hsKey = name => 'hs_' + String(name || '').split(' ').pop()
  .normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z]/g,'');
function faceOf(name, num, px){
  const a = typeof ART !== 'undefined' && ART[hsKey(name)];
  if (a) return '<span class="face" style="width:'+px+'px;height:'+px+'px">' +
                '<img src="'+a.src+'" alt="" width="'+px+'" height="'+px+'">' +
                (num != null ? '<i>'+num+'</i>' : '') + '</span>';
  return sweaterSVG(px, num);
}
function sweaterSVG(px, num){
  const n = String(num == null ? '' : num);
  const fs = n.length > 1 ? 21 : 24;
  return '<svg class="swtr" viewBox="0 0 100 100" aria-hidden="true" width="'+px+'" height="'+px+'">'+
    /* body in club navy with a white outline, so it reads on any ground */
    '<path fill="#00205B" stroke="#FFFFFF" stroke-width="3.2" stroke-linejoin="round" d="'+
      'M31 20 L43 13 q7 6 14 0 L69 20 l13 10-8 13-7-5v41q0 4-4 4H37q-4 0-4-4V38l-7 5-8-13z"/>'+
    /* the white shoulder yoke */
    '<path fill="#FFFFFF" d="M33.5 20.5 L43 14.5 q7 5.6 14 0 L66.5 20.5 l-2.6 7.4q-13.4 4.6-26.8 0z"/>'+
    crestG(50, 43, 0.30, '#FFFFFF') +
    (n ? '<text x="50" y="76" text-anchor="middle" fill="#FFFFFF" font-size="'+fs+
      '" font-weight="800" font-family="Archivo,Helvetica,Arial,sans-serif" '+
      'style="font-variant-numeric:tabular-nums">'+n+'</text>' : '')+
  '</svg>';
}

/* ── the row every game shares ────────────────────────────────────
   jersey, position, name, a real season line, the value being played
   for, and a bar for where that value sits in the field. One function,
   so a row in the picker and a row in Beat Stormy are the same object. */
const SEASON = Object.fromEntries(R.map(p => [p.name, p]));

/* ── season context, shared by every game ─────────────────────────
   SEASON is the trivia roster and carries no takeaway column, so graft
   it on from the roster file the projections come from. This whole
   block sits here, above game 2, because five games read it now and a
   const still in its temporal dead zone is a silent boot failure. */
(function(){
  PD.roster.forEach(p => { const s = SEASON[p.n]; if (s && s.tk == null) s.tk = p.tk; });
})();
/* ══ SLATE GAMES ═════════════════════════════════════════════════
   Games 3, 5 and 6 used to be quizzes about a season that had already
   finished, and one of them asked a fan to guess our expected-goals
   model. Both are the wrong shape for a game-day app: a fan on the
   concourse is not there to be tested on last April, and the model is
   not the thing they came to argue about.

   All three are now slates. You lock your picks, the game plays, and
   the official box score settles them. Nothing in here can be answered
   by knowing how Citrus works, only by knowing the team.

   Every line is drawn from the player's OWN season rate out of the
   roster file, floored to the nearest half, so a line can never push
   and a fan can always see why it sits where it does.                */

(function(){ /* SEASON is the trivia roster and carries no takeaways */
  PD.roster.forEach(p => { const s = SEASON[p.n]; if (s && s.tk == null) s.tk = p.tk; });
})();
const SLATE = BOX_L.filter(r => SEASON[r.name] && SEASON[r.name].tk != null);
const perGame = (name, k) => {
  const s = SEASON[name];
  if (!s || !s.gp || s[k] == null) return 0;
  const r = s[k] / s.gp;
  return isFinite(r) ? r : 0;
};
const lineFor = (name, k) => Math.floor(perGame(name, k)) + 0.5;

/* ── the kit pool ─────────────────────────────────────────────────
   This was the twenty-three skaters of the Citrus Projections 2.0
   opening-night roster, and it was the wrong list. The page says
   "Game 01, live" and settles the six slots against the game the
   score bug is replaying, Anaheim at Toronto. That roster and this
   one overlap by ten men: thirteen of the twenty-three were not in
   the building. Pick one and the slot could never settle, so it sat
   on a tick to the final buzzer and said nothing about why.

   The pool is now the seventeen who dressed for this game and have a
   season behind them, which is the same seventeen Beat Stormy and the
   three slates already use. One roster across every live game.

   The number on a row moves with it. A projection built for 29
   September cannot be shown against a game played on 12 March, so the
   row carries the man's own season rate, per game, out of the same
   roster file every other season number on this page comes from. It is
   labelled as a rate everywhere it appears, never as a projection.  */
const KIT_POOL = SLATE.map(r => {
  const s = SEASON[r.name];
  const o = { name: s.name, pos: s.pos, num: s.num || r.num };
  PARTS.forEach(P => { o[P.k] = +perGame(s.name, P.k).toFixed(2); });
  return o;
});

/* The ceiling is NOT the sum of the six category leaders. Matthews leads
   goals and shots and can only fill one slot. This is the exact best legal
   assignment of six different skaters to six slots, branch-and-bound.     */
const PERFECT = (() => {
  const cap = PARTS.map(P => Math.max(...KIT_POOL.map(p => val(p,P.k))));
  let best = 0, bestBuild = null; const used = new Set(), cur = [];
  (function dfs(i, acc){
    if (i === PARTS.length){ if (acc > best){ best = acc; bestBuild = [...cur]; } return; }
    let bound = acc; for (let j = i; j < PARTS.length; j++) bound += cap[j];
    if (bound <= best) return;
    for (const p of [...KIT_POOL].sort((a,b) => b[PARTS[i].k] - a[PARTS[i].k])){
      if (used.has(p.name)) continue;
      used.add(p.name); cur.push(p);
      dfs(i + 1, acc + val(p, PARTS[i].k));
      cur.pop(); used.delete(p.name);
    }
  })(0,0);
  return { total: +best.toFixed(2), build: bestBuild };
})();
const GREEDY   = +PARTS.reduce((s,P) => s + Math.max(...KIT_POOL.map(p => val(p,P.k))), 0).toFixed(2);
const BEST_ONE = KIT_POOL.reduce((m,p) => sixCat(p) > sixCat(m) ? p : m, KIT_POOL[0]);
const SLATE_CATS = [
  {k:'sog', l:'shots on goal', s:'SOG'}, {k:'hit', l:'hits',      s:'HIT'},
  {k:'blk', l:'blocks',        s:'BLK'}, {k:'p',   l:'points',    s:'PTS'},
  {k:'tk',  l:'takeaways',     s:'TK' },
];
const liveVal = (name, k) => (KIT_LIVE[k] ? CLOCK.live(name)[k]
                            : (CLOCK.over ? BOXF[name][k] : null));
const PAYOUT = {6:150, 5:60, 4:25, 3:10, 2:0, 1:0, 0:0};
const PAY_5  = {5:120, 4:45, 3:15, 2:0, 1:0, 0:0};

function slateStatus(){
  return CLOCK.over ? 'final' : CLOCK.t > 0 ? 'live' : 'pre';
}
function payRow(pay, n){
  return '<div class="payrow">' + Object.keys(pay).sort((x,y)=>y-x).filter(k=>pay[k])
    .map(k => '<span><b>' + k + ' of ' + n + '</b>' + pay[k] + '</span>').join('') + '</div>';
}

const GRADE  = {'Elite':'elite','Above Avg':'above','Average':'avg','Below Avg':'below','Low':'low'};
const STATL  = {g:['G','goals'], a:['A','assists'], sog:['SOG','shots'],
                hit:['HIT','hits'], blk:['BLK','blocks'], pim:['PIM','penalty mins'],
                p:['P','points'], w:['W','wins'], sv:['SV','saves'], so:['SO','shutouts'],
                tk:['TK','takeaways']};
function seasonLine(p, k){
  const s = SEASON[p.name]; if (!s) return '';
  const bits = [];
  if (k && STATL[k] && s[k] != null){
    bits.push('<em>'+s[k]+'</em> '+STATL[k][0]);
    if (s.gp) bits.push('<s>·</s>'+(s[k]/s.gp).toFixed(2)+'/gm');
  } else if (!s.gk){
    bits.push('<em>'+s.g+'</em> G'); bits.push('<em>'+s.a+'</em> A');
  } else {
    bits.push('<em>'+s.w+'</em> W'); if (s.svp) bits.push((s.svp*100).toFixed(1)+' SV%');
  }
  bits.push('<s>·</s>'+s.gp+' GP');
  if (!s.gk && s.xgr && GRADE[s.xgr]) bits.push('<span class="sc '+GRADE[s.xgr]+'">'+s.xgr+'</span>');
  return bits.join(' ');
}
/* o: {k, val, unit, frac, taken, on, share, onclick} */
function prow(p, o){
  o = o || {};
  const b = el('button','prow'+(o.on?' on':'')+(o.taken?' gone':''));
  b.type = 'button';
  if (o.taken) b.disabled = true;
  const rt = o.val == null ? '' :
    '<div class="rt"><b class="tnum">'+o.val+'</b>'+
    (o.unit? '<span class="sh">'+o.unit+'</span>':'')+
    (o.frac!=null? '<div class="bar"><i style="width:'+Math.round(o.frac*100)+'%"></i></div>':'')+'</div>';
  b.innerHTML =
    '<div class="jn">'+faceOf(p.name, p.num, 38)+'</div>'+
    '<div><div class="l1"><span class="pc '+p.pos+'">'+p.pos+'</span><b>'+p.name+'</b></div>'+
    '<div class="l2">'+(p.num ? '<em class="jnum">#'+p.num+'</em><s>·</s>' : '')+
    (o.taken ? '<em>Already on '+o.taken+'</em>' : (o.line != null ? o.line : seasonLine(p, o.k)))+
    (o.share? ' <s>·</s>'+o.share : '')+'</div></div>'+ rt;
  if (!o.taken && o.onclick) b.onclick = o.onclick;
  return b;
}

/* ══ CITRUS CARLTON ══════════════════════════════════════════════
   The kit page used to be six cards on a grid, which is a form, not a
   character. It is now a paper doll: the club's own bear, drawn in the
   Citrus house style, standing in the middle of the page with nothing
   on but a sweater, and six pieces of gear that arrive as you fill the
   slots. Every piece is dim and hollow until a Leaf is behind it, then
   it fills in and, once the puck drops, carries what that man has
   actually done tonight.

   Two things about him worth saying out loud in the room.

   Carlton is MLSE's mascot and their trademark, right down to the 60
   on his back for 60 Carlton Street. This is a Citrus rendering of
   someone else's character, shown back to the people who own him.
   That is normal pitch practice and it is worth saying rather than
   letting a screenshot say it.

   And the drawing is honest about being a drawing. Six PNG layers on a
   shared canvas -- carlton-base plus one per piece of kit -- swap the
   whole figure the moment they land, and until every one of the seven
   is on disk the build keeps the vector, because half a paper doll is
   worse than none. See CARLTON-BRIEF.md.                            */
/* ── one render, six masks ─────────────────────────────────────────
   The brief asked for seven transparent layers stacked pixel for pixel.
   No diffusion model registers seven separate generations that precisely,
   so the ask became one render in the vector's own pose and the six pieces
   became clip regions over it. carlton-figure landed and the pose holds.

   The masks are NOT the vector's paths. That was the plan and it was
   wrong: overlaying the vector's six shapes on the render showed the shin
   pads short and high by about twenty units and the skates missing their
   blades, because the render's legs are longer than the drawing's. The
   colour-class IoU that came with the file measured the whole figure --
   fur 95.7%, sweater 91.1% -- which says the bear is in the right place,
   not that each piece is.

   So the regions below are measured off the render itself and divided by
   three from 1140x1410 into the 380x470 space the page draws in. Not by
   connected components -- v2 is one blob apart from the puck, exactly as
   warned -- but by material: the stick is the only warm wood on the right
   of the frame, the leg pads the only neutral grey between the pants and
   the boots, the shoulder caps the only light panel between the jaw and
   the sleeve. Every piece was then re-measured row by row, because a
   bounding box on a diagonal stick is mostly not stick.

   Two adjacencies are unavoidable and both are harmless. The shoulder
   caps meet the jaw, so ten units of the caps' inner corner is fur that
   lights with them -- fur beside fur. The stick's butt sits above the
   right glove, so it gets a region of its own rather than lighting with
   the hands or, worse, staying bright while the shaft below it is dim.

   THEN THEY BECAME THE ONLY WAY IN, so they are no longer the art. The
   six rows beside him used to be buttons and they carried the whole
   game; now Carlton carries it, and a region measured to the outline of
   a shin pad is not a tap target, it is a dexterity test. Every region
   below is grown past its piece into whatever space is free around it:
   the stick's five stepped rects collapse into one fat run of shaft
   plus a blade, and the puck goes from 29px across on a phone to 37.

   Nothing outside the figure is painted, so growing a region costs
   nothing except where it would reach another piece. Every pair is
   checked clear -- no two rects intersect -- and the smallest primary
   target on a 360px phone is the puck at 37 x 37. */
const CARL_HIT = {
  hit: [[86,152,58,62],  [208,150,60,68]],    // shoulder caps
  a:   [[50,247,70,72],  [230,249,72,60]],    // gloves, cuffs included
  blk: [[100,334,76,71], [180,334,76,71]],    // leg pads
  tk:  [[100,405,77,56], [178,405,78,56]],    // boots and blades
  /* the butt is 38 x 19 and will never be a real target; it is here so
     that tapping the visible end of the stick means the stick. The shaft
     is the one that matters, and it is 42 x 60 on a phone. */
  g:   [[246,230,38,19], [256,309,64,92], [278,392,62,32]],
  sog: [[322,334,56,56]],
};

/* where each cut layer sits in the 380 x 470 box, straight out of carve.py.
   A layer is the piece's own silhouette on a transparent crop, so these are
   placement, not clipping -- nothing here decides what is visible. */
const CARL_LAY = {
  hit:[85.3,152,183,69],  a:[52.3,247,249.7,74],
  blk:[100.7,335,154.3,70.7],   tk:[101,403.7,155,48.7],
  g:[254.3,241.3,85,179],   sog:[322.7,340.3,44,43.7]
};
const CARL_LAYERS = ['hit','a','blk','tk','g','sog'];
/* seven or none. A rendered bear wearing one drawn shin pad is worse than
   the drawn bear, so a missing layer drops the whole figure to the vector. */
const CARL_ART = () => typeof ART !== 'undefined' && !!ART.carl_base &&
                       CARL_LAYERS.every(id => !!ART['carl_' + id]);

function carltonRender(){
  /* Rectangles over one flat render were the first attempt and they are
     visibly wrong: dimming a rect that crosses the sweater draws a hard
     block across the yoke and the jaw. So carve.py cuts the render into a
     base and six pieces by material, and a dim piece is now a ghost of the
     piece with the bear behind it untouched.

     The pieces paint but do not listen -- their crops overlap (the stick's
     box covers the right glove's) and whichever painted last would eat the
     other's taps. The listening is done by the CARL_HIT rects on top,
     which are disjoint and bigger than the art.

     Each piece's rects live in ONE group, and the group is the control:
     tabindex, a role and a name on the group means six tab stops rather
     than fourteen, and it means "the skates" is one thing to a screen
     reader rather than a left one and a right one. */
  const box = (cls, id, href, r) =>
    '<image class="' + cls + '" data-id="' + id + '" href="' + href +
    '" x="' + r[0] + '" y="' + r[1] + '" width="' + r[2] + '" height="' + r[3] + '"/>';
  const hitz = r =>
    '<rect class="hitz" x="' + r[0] + '" y="' + r[1] +
    '" width="' + r[2] + '" height="' + r[3] + '"/>';
  const door = id =>
    '<g class="kitdoor" data-id="' + id + '" tabindex="0" role="button">' +
    CARL_HIT[id].map(hitz).join('') + '</g>';

  /* paint in layer order, because the crops overlap and the stick has to
     land over the glove. Tab in PARTS order, because that is the order of
     the list beside him and a tab ring that jumps hit, hands, pads, skates,
     stick, puck against a list that reads stick, hands, shots... is two
     different games. */
  let pieces = '', doors = '';
  CARL_LAYERS.forEach(id => { pieces += box('kitp kitl', id, ART['carl_' + id].src, CARL_LAY[id]); });
  PARTS.forEach(P => { doors += door(P.id); });

  /* aria-hidden on the svg root would take the six doors with it, so the
     root keeps a name and the base image is the thing that is decorative */
  return '<svg class="carlsvg carlrender" viewBox="0 0 380 470" role="group" ' +
    'aria-label="Carlton, and his six pieces of kit">' +
    '<ellipse class="cshade" cx="176" cy="452" rx="106" ry="14"/>' +
    '<image class="cbase" href="' + ART.carl_base.src + '" x="0" y="0" width="380" height="470"/>' +
    pieces + doors + '</svg>';
}

/* anchors for the live pips, as a share of the 380 x 470 box, so the
   badge sits on the piece it is talking about at any figure size */
const CARL_PIN = {
  hit:[63.2,40.4], a:[23.2,63.8], g:[73.1,72.1],
  sog:[90.5,77.0], blk:[33.2,78.3], tk:[57.4,88.9]
};

/* two-pass limbs and stick: the same path stroked wide in the outline
   colour and again narrow in the fill colour. It gives a limb a real
   silhouette without hand-solving the outline of a bent tube. */
const cS = (cls, d, w) => '<path class="' + cls + '" d="' + d + '" stroke-width="' + w + '"/>';

function carlBoot(dx){                       /* one skate, dx apart */
  const t = 'transform="translate(' + dx + ' 0)"';
  return '<g ' + t + '>' +
    '<path class="k" d="M119 398 h42 q14 0 15 13 l1 15 q1 12 -12 12 h-46 q-12 0 -12 -12 v-16 q0 -12 11 -12 z"/>' +
    '<rect class="k" x="118" y="434" width="10" height="9" rx="2"/>' +
    '<rect class="k" x="156" y="434" width="10" height="9" rx="2"/>' +
    '<rect class="ka" x="104" y="440" width="70" height="9" rx="4.5"/>' +
    '<path class="ks" d="M124 410 h34 M124 422 h34" stroke-width="4"/></g>';
}
function carlShin(dx){                       /* one shin pad */
  const t = 'transform="translate(' + dx + ' 0)"';
  return '<g ' + t + '>' +
    '<circle class="k" cx="140" cy="344" r="18"/>' +
    '<path class="k" d="M116 336 h48 q10 0 10 10 v50 q0 10 -10 10 h-48 q-10 0 -10 -10 v-50 q0 -10 10 -10 z"/>' +
    '<rect class="ka" x="104" y="356" width="70" height="8" rx="4"/>' +
    '<rect class="ka" x="104" y="380" width="70" height="8" rx="4"/></g>';
}
function carlGlove(x, y, tx){                /* one mitt, tx = thumb side */
  return '<g>' +
    '<rect class="k" x="' + (x + (tx < 0 ? -10 : 44)) + '" y="' + (y + 10) + '" width="18" height="30" rx="9"/>' +
    '<rect class="k" x="' + x + '" y="' + y + '" width="52" height="54" rx="16"/>' +
    '<rect class="ka" x="' + (x - 4) + '" y="' + (y + 40) + '" width="60" height="17" rx="7"/>' +
    '<path class="ks" d="M' + (x + 14) + ' ' + (y + 8) + ' v30 M' + (x + 28) + ' ' + (y + 8) + ' v30" stroke-width="3.6"/></g>';
}
function carlCap(mirror){                    /* one shoulder cap */
  const t = mirror ? ' transform="translate(352 0) scale(-1 1)"' : '';
  return '<g' + t + '>' +
    '<path class="k" d="M142 166 q-6 -10 -18 -8 q-30 6 -35 32 q-4 22 17 25 l30 -6 q8 -22 6 -43 z"/>' +
    '<path class="ks" d="M95 186 q18 -5 34 -2" stroke-width="4"/></g>';
}

function carltonSVG(){
  if (CARL_ART()) return carltonRender();
  return '<svg class="carlsvg" viewBox="0 0 380 470" role="img" aria-hidden="true">' +
  '<defs><clipPath id="carlTorso"><path d="M118 196 q2 -22 22 -27 l30 -8 q6 6 12 0 l30 8 q20 5 22 27 l8 76 q2 14 -13 14 h-106 q-15 0 -13 -14 z"/></clipPath></defs>' +

  '<ellipse class="cshade" cx="176" cy="452" rx="106" ry="14"/>' +

  /* ── the skates ── */
  '<g class="kitp" data-id="tk"><rect class="hitz" x="176" y="390" width="84" height="62"/>' + carlBoot(76) + '</g>' +
  '<g class="kitp" data-id="tk"><rect class="hitz" x="100" y="390" width="84" height="62"/>' + carlBoot(0) + '</g>' +
  /* ── the shin pads ── */
  '<g class="kitp" data-id="blk"><rect class="hitz" x="98" y="336" width="84" height="78"/>' + carlShin(0) + '</g>' +
  '<g class="kitp" data-id="blk"><rect class="hitz" x="180" y="336" width="84" height="78"/>' + carlShin(76) + '</g>' +

  /* pants, over the top of the pads the way they sit on a real leg */
  '<path class="cpant" d="M124 276 h104 q14 0 16 13 l5 38 q2 13 -12 13 h-122 q-14 0 -12 -13 l5 -38 q2 -13 16 -13 z"/>' +
  '<path class="cstripe" d="M112 312 h128"/>' +

  /* the sweater */
  '<path class="csweat" d="M118 196 q2 -22 22 -27 l30 -8 q6 6 12 0 l30 8 q20 5 22 27 l8 76 q2 14 -13 14 h-106 q-15 0 -13 -14 z"/>' +
  '<g clip-path="url(#carlTorso)">' +
    '<path class="cyoke" d="M104 200 q12 -24 36 -31 l36 -10 l36 10 q24 7 36 31 l-7 15 q-13 -20 -33 -25 l-32 -9 l-32 9 q-20 5 -33 25 z"/>' +
    '<rect class="cyoke" x="100" y="252" width="160" height="11"/>' +
    '<rect class="cyoke" x="100" y="269" width="160" height="6"/>' +
  '</g>' +
  '<path class="csweatln" d="M118 196 q2 -22 22 -27 l30 -8 q6 6 12 0 l30 8 q20 5 22 27 l8 76 q2 14 -13 14 h-106 q-15 0 -13 -14 z"/>' +

  /* the crest. Where the club's own mark goes, a citrus slice: this is
     the one place in the build the accent is allowed to be the subject */
  '<circle class="ccrestw" cx="176" cy="220" r="28"/>' +
  '<circle class="ccrest"  cx="176" cy="220" r="21"/>' +
  '<g class="ccrestseg">' +
    '<path d="M179 220 L196 220"/><path d="M177.5 222.6 L186 237.3"/>' +
    '<path d="M174.5 222.6 L166 237.3"/><path d="M173 220 L156 220"/>' +
    '<path d="M174.5 217.4 L166 202.7"/><path d="M177.5 217.4 L186 202.7"/>' +
  '</g>' +
  '<circle class="ccrestw" cx="176" cy="220" r="4"/>' +

  /* sleeves */
  cS('csleeveo', 'M126 198 C 106 216, 94 244, 93 266', 38) +
  cS('csleeve',  'M126 198 C 106 216, 94 244, 93 266', 30) +
  cS('ccuff',    'M97 246 C 95 254, 93 260, 93 266', 30) +
  cS('csleeveo', 'M226 198 C 246 216, 258 238, 260 260', 38) +
  cS('csleeve',  'M226 198 C 246 216, 258 238, 260 260', 30) +
  cS('ccuff',    'M255 242 C 258 250, 259 255, 260 260', 30) +

  /* ── the shoulders ── */
  '<g class="kitp" data-id="hit"><rect class="hitz" x="210" y="166" width="58" height="66"/>' + carlCap(1) + '</g>' +
  '<g class="kitp" data-id="hit"><rect class="hitz" x="88" y="166" width="58" height="66"/>' + carlCap(0) + '</g>' +

  /* ── the stick ── */
  '<g class="kitp" data-id="g">' +
    cS('hitz', 'M262 250 L288 398', 42) +
    cS('kso', 'M262 250 L288 398', 17) + cS('ksf', 'M262 250 L288 398', 10) +
    cS('kso', 'M286 400 L328 411', 19) + cS('ksf', 'M286 400 L328 411', 12) +
    cS('kta', 'M268 278 L274 306', 11) +
  '</g>' +

  /* ── the hands ── */
  '<g class="kitp" data-id="a"><rect class="hitz" x="48" y="248" width="82" height="76"/>' + carlGlove(66, 258, -1) + '</g>' +
  '<g class="kitp" data-id="a"><rect class="hitz" x="226" y="240" width="82" height="76"/>' + carlGlove(236, 250, 1) + '</g>' +

  /* ── the release ── */
  '<g class="kitp" data-id="sog"><rect class="hitz" x="316" y="334" width="60" height="60"/>' +
    '<circle class="kpuck" cx="344" cy="362" r="24"/>' +
  '</g>' +

  /* the bear */
  '<g class="chead">' +
    '<circle class="cfur" cx="122" cy="40" r="27"/><circle class="cear" cx="122" cy="40" r="13"/>' +
    '<circle class="cfur" cx="230" cy="40" r="27"/><circle class="cear" cx="230" cy="40" r="13"/>' +
    '<circle class="cfur" cx="176" cy="98" r="68"/>' +
    '<ellipse class="cmuz" cx="176" cy="126" rx="41" ry="30"/>' +
    '<ellipse class="cink" cx="176" cy="110" rx="14" ry="10.5"/>' +
    '<path class="cline" d="M176 121 v9 M176 130 q-13 13 -25 2 M176 130 q13 13 25 2"/>' +
    '<circle class="cink" cx="146" cy="82" r="9"/><circle class="cink" cx="206" cy="82" r="9"/>' +
    '<circle class="cglint" cx="149.5" cy="78" r="3.2"/><circle class="cglint" cx="209.5" cy="78" r="3.2"/>' +
  '</g>' +
  '</svg>';
}

/* the figure, the pips and the caption. Rebuilt only when the kit
   changes; the pips update in place on the clock. */
let carlBuilt = false;
function drawCarl(){
  const host = $('#carl'); if (!host) return;
  if (!carlBuilt){
    host.innerHTML = carltonSVG() +
      PARTS.map((P, i) => '<span class="kitpin" data-id="' + P.id + '" style="left:' +
        CARL_PIN[P.id][0] + '%;top:' + CARL_PIN[P.id][1] + '%;--kd:' +
        (i * 0.17).toFixed(2) + 's"></span>').join('') ;

    /* One door per piece, whichever figure is on the page. The render
       emits its own; the vector is ten groups because a pair is two
       halves, and ten tab stops for six controls is worse than none.
       The other half stays clickable, it just is not a second stop --
       and hot() lights both, so the focused piece is never ambiguous. */
    PARTS.forEach(P => {
      const d = host.querySelector('.kitdoor[data-id="' + P.id + '"]')
             || host.querySelector('g.kitp[data-id="' + P.id + '"]');
      if (!d) return;
      d.classList.add('kitdoor');
      d.setAttribute('tabindex', '0');
      d.setAttribute('role', 'button');
    });

    const at = e => { const g = e.target.closest('[data-id]');
      return g && g.dataset.id ? PARTS.find(x => x.id === g.dataset.id) : null; };
    host.addEventListener('click', e => { const P = at(e); if (P) openPicker(P); });
    /* a <g> with a tabindex is focusable but it is not a button, so
       Enter and Space do nothing unless somebody says so */
    host.addEventListener('keydown', e => {
      if (e.key !== 'Enter' && e.key !== ' ' && e.key !== 'Spacebar') return;
      const P = at(e); if (!P) return;
      e.preventDefault(); openPicker(P);
    });
    /* a pair is two groups, so lighting one skate on hover and not the
       other would read as a bug. Done here rather than with :has(),
       which this file cannot assume in a browser it has never met. */
    const hot = g => { const id = g && g.dataset.id;
      host.querySelectorAll('.kitp,.kitdoor').forEach(x =>
        x.classList.toggle('hot', !!id && x.dataset.id === id)); };
    host.addEventListener('mouseover', e => hot(e.target.closest('[data-id]')));
    host.addEventListener('mouseleave', () => hot(null));
    host.addEventListener('focusin',  e => hot(e.target.closest('.kitdoor')));
    host.addEventListener('focusout', () => hot(null));
    carlBuilt = true;
  }
  PARTS.forEach(P => {
    const chosen = pick[P.id];
    host.querySelectorAll('.kitp[data-id="' + P.id + '"]')
        .forEach(g => g.classList.toggle('on', !!chosen));
    /* the door carries everything the row beside it used to say, because
       the row is not a control any more and this is */
    const lead = [...KIT_POOL].sort((a,b) => b[P.k] - a[P.k])[0];
    const d = host.querySelector('.kitdoor[data-id="' + P.id + '"]');
    if (d) d.setAttribute('aria-label', P.part + ', ' + P.cat + '. ' + (chosen
      ? chosen.name + ' is in this slot, worth ' + val(chosen, P.k).toFixed(2) +
        ' fantasy points. Activate to change him.'
      : 'Empty. Leader tonight ' + lead.name + ', ' + lead[P.k].toFixed(2) +
        ' a game. Activate to pick a Leaf.'));
  });
  carlPips();
  const cap = $('#carlCap'); if (!cap) return;
  const n = Object.keys(pick).length;
  cap.innerHTML = n === 0
    ? 'Carlton has the sweater and nothing else. <b>Tap a piece of his kit</b> to put a Leaf in it.'
    : n < 6 ? '<b>' + n + ' of 6</b> pieces on Carlton. Tap another, ' + (6 - n) + ' to go.'
    : CLOCK.over ? '<b>Dressed, and final.</b> Every piece has settled.'
                 : '<b>Dressed.</b> Every piece scores as the game goes.';
}
/* the pip does two jobs on the same dot. Empty, it is the invitation: a
   citrus ring on the piece, pulsing, because the figure is the only way
   in and a piece at 26% does not look like a control. Filled, it is the
   number that piece has put up tonight. It never carries a zero dressed
   up as a fact, and it never carries a tick and a ring at once. */
function carlPips(){
  const host = $('#carl'); if (!host) return;
  PARTS.forEach(P => {
    const pin = host.querySelector('.kitpin[data-id="' + P.id + '"]'); if (!pin) return;
    const chosen = pick[P.id];
    if (!chosen){ pin.className = 'kitpin ask'; pin.textContent = ''; pin.dataset.id = P.id; return; }
    const known = !!KIT_LIVE[P.k] || CLOCK.over;
    const n = !BOXF[chosen.name] ? null
      : (KIT_LIVE[P.k] ? CLOCK.live(chosen.name)[P.k] : BOXF[chosen.name][P.k]);
    pin.className = 'kitpin on' + (known && n > 0 ? ' hot' : '');
    pin.textContent = known && n != null ? String(n) : '✓';
    pin.dataset.id = P.id;
  });
}

/* ── the kit ──────────────────────────────────────────────────────
   Not doors any more. These six were buttons and they were the whole
   game: "+ Pick a Leaf" six times, with Carlton standing beside them
   as decoration. Carlton is the game now, so the list is a read-out --
   what each slot is worth, who is in it, who is leading it tonight --
   and an empty row names the piece to go and tap. A legend, not a menu.

   They keep no role and no tabindex on purpose. The control is the
   piece on the figure, it carries the same words in its aria-label, and
   two things claiming to be the same control is worse than one. */
function drawParts(){
  const box = $('#parts'); box.innerHTML = '';
  PARTS.forEach(P => {
    const chosen = pick[P.id];
    const lead   = [...KIT_POOL].sort((a,b) => b[P.k] - a[P.k])[0];
    const t = el('div','eq'+(chosen?' filled':''));
    t.dataset.id = P.id;          /* the row and the piece are the same slot */
    t.style.setProperty('--eqc','var('+PART_C[P.id]+')');
    t.innerHTML =
      '<div class="prop">'+eqArt(P.id)+'</div>'+
      '<div class="nmcat"><div class="pt">'+P.part+'</div><div class="pcat">'+P.cat+'</div></div>'+
      '<div class="slot">'+(chosen
        ? '<div class="who"><span class="pc '+chosen.pos+'">'+chosen.pos+'</span>'+
          '<span class="nm2">'+chosen.name+'</span>'+
          '<span class="val tnum">'+chosen[P.k].toFixed(2)+'</span></div>'
        /* the sentence is one flex child, not four: a gap meant for the
           icon was landing between every word and the bold piece name */
        : '<div class="empty"><svg viewBox="0 0 24 24" aria-hidden="true">'+
          '<circle class="tapdot" cx="12" cy="12" r="3.1"/>'+
          '<path d="M18.4 5.6a9 9 0 0 1 0 12.8M5.6 18.4a9 9 0 0 1 0-12.8"/></svg>'+
          '<span>Tap <b>'+P.part.toLowerCase()+'</b> on Carlton</span></div>')+
      '</div>'+
      (chosen ? '<div class="lead">Worth <b>+'+val(chosen,P.k).toFixed(2)+'</b> fantasy points</div>'
              : '<div class="lead">Leader tonight: '+last(lead.name)+' '+lead[P.k].toFixed(2)+'</div>');
    box.appendChild(t);
  });
  drawCarl();
}

/* ── the picker ───────────────────────────────────────────────────
   Modal on purpose: while a slot is open nothing else is actionable,
   which is what makes the six-tile page readable in the first place. */
let shPart = null, shPrev = null;
function openPicker(P){
  shPart = P; shPrev = document.activeElement;
  const sheet = $('#pickSheet'), list = $('#shList');
  sheet.querySelector('.shcard').style.setProperty('--eqc','var('+PART_C[P.id]+')');
  sheet.querySelector('.shcard').style.setProperty('--ac','var('+PART_C[P.id]+')');
  $('#shTitle').textContent = P.part;
  $('#shSub').textContent   = P.cat + ' · per game this season';
  const chosen = pick[P.id];
  const takenBy = {};
  Object.entries(pick).forEach(([id,p]) => { if (id !== P.id) takenBy[p.name] = PARTS.find(x=>x.id===id).part; });
  const ranked = [...KIT_POOL].sort((a,b) => b[P.k] - a[P.k]);
  const top = ranked[0][P.k] || 1;
  $('#shNote').innerHTML = 'Every Leaf fills one slot only, ' +
    (Object.keys(takenBy).length ? '<b>'+Object.keys(takenBy).length+'</b> already placed and greyed below.'
                                 : 'nobody is placed yet.');
  list.innerHTML = '';
  ranked.forEach(p => {
    const isMine = chosen && chosen.name === p.name;
    /* real social proof: not a modelled percentage, the actual count of
       fans in this room who put this man in this slot. Absent until at
       least one other build exists, because a share of one is not one. */
    const sh = (typeof ROOM !== 'undefined' && ROOM.ok) ? ROOM.ultShare(P.id, p.name) : null;
    list.appendChild(prow(p, {
      k: P.k, val: p[P.k].toFixed(2), unit: STATL[P.k][1], frac: p[P.k]/top,
      share: sh && sh.n ? '<em style="color:var(--fy)">'+sh.n+' of '+sh.of+' in the room</em>' : null,
      taken: takenBy[p.name] || null, on: isMine,
      onclick: () => {
        if (isMine) delete pick[P.id]; else { pick[P.id] = p; Snd.pick(); }
        drawParts(); tally(); closePicker();
      }
    }));
  });
  sheet.classList.add('on');
  document.body.style.overflow = 'hidden';
  const f = list.querySelector('.prow:not([disabled])'); if (f) f.focus();
}
function closePicker(){
  $('#pickSheet').classList.remove('on');
  document.body.style.overflow = '';
  if (shPrev && shPrev.focus) shPrev.focus();
  shPart = null;
}
document.addEventListener('keydown', e => {
  if (e.key === 'Escape' && $('#pickSheet').classList.contains('on')) closePicker();
});

/* the fixture strip: no player is shown without the game around him */
function drawGameDay(){
  const box = $('#ultDay'); if (!box) return;
  box.innerHTML =
    /* The fixture used to live here in two chips. The score bug is sticky
       on every page and already says Anaheim at Toronto, 12 March 2026,
       Scotiabank Arena, so these were the same three facts twice, and on
       a phone they pushed the two chips that are actually about YOUR
       build off the side of a strip with no sign it scrolled. */
    '<span class="gd"><i>Slots filled</i><b id="ultFilled">0 of 6</b></span>'+
    '<span class="gd"><i>Perfect build</i><b>'+PERFECT.total.toFixed(2)+' fpts</b></span>';
}

function tally(){
  const t = +PARTS.reduce((s,P) => s + (pick[P.id] ? val(pick[P.id],P.k) : 0), 0).toFixed(2);
  const one = sixCat(BEST_ONE);
  $('#ultTotal').textContent = t.toFixed(2);
  $('#ultFill').style.width  = Math.min(100, t / PERFECT.total * 100)+'%';
  $('#ultMark').style.left   = (one / PERFECT.total * 100)+'%';
  $('#mlabBest').textContent    = last(BEST_ONE.name)+' '+one.toFixed(2)+'. Best single Leaf tonight';
  $('#mlabPerfect').textContent = PERFECT.total.toFixed(2)+' perfect';
  const d = t - one;
  $('#ultDelta').innerHTML = !Object.keys(pick).length ? 'not built yet'
    : (d >= 0 ? '<span class="up">+'+d.toFixed(2)+'</span>' : '<span class="dn">'+d.toFixed(2)+'</span>');
  ultLive();
  $('#ultSubmit').disabled = Object.keys(pick).length < 6 || ultBanked;
  const fc = $('#ultFilled'); if (fc) fc.textContent = Object.keys(pick).length+' of 6';
  return t;
}

/* ── the kit, scoring against the real game ───────────────────────
   The build stops being a guess the moment the puck drops. Each slot
   shows what that Leaf has actually done tonight, and the total beside
   the projection is real points, not projected ones.

   Goals, assists and shots come off the event feed so they move during
   the game. Hits, blocks and takeaways only exist in the official box
   score, so they arrive at the final buzzer and the panel says so
   rather than pretending to know them early.                        */
/* Provable mid-game from the shot feed. Points belong here and were
   missing: CLOCK.live() already returns p as g + a off the same events,
   so a points line sat on "settles at the buzzer" for sixty minutes
   while the two numbers that make it moved on the page above it. That
   gate ran three games, not one -- Rank 'Em, Heat Check and Who Goes
   Off all take points as a category. */
const KIT_LIVE = {g:1, a:1, p:1, sog:1};
function ultLive(){
  const host = $('#ultLive'); if (!host) return;
  let total = 0, any = false;
  PARTS.forEach(P => {
    const chosen = pick[P.id]; if (!chosen) return;
    const row = BOXF[chosen.name];
    if (!row) return;
    any = true;
    const settled = KIT_LIVE[P.k] || CLOCK.over;
    const n = KIT_LIVE[P.k] ? CLOCK.live(chosen.name)[P.k] : (CLOCK.over ? row[P.k] : 0);
    if (settled) total += n * SC[P.k];
  });
  host.textContent = total.toFixed(2);
  host.parentElement.classList.toggle('dim', !any);
  const s = $('#ultSettle');
  if (s) s.innerHTML = !any ? 'Fill the kit, then start the clock and watch it score.'
    : CLOCK.over ? '<b>Final.</b> Every slot has settled.'
    : '<b>' + BOX_ONLY_NOTE + '</b> Goals, assists and shots are live.';
  drawKitLive();
  carlPips();
}
function drawKitLive(){
  document.querySelectorAll('#parts .eq').forEach((tile, i) => {
    const P = PARTS[i], chosen = pick[P.id];
    let strip = tile.querySelector('.eqlive');
    if (!chosen || !BOXF[chosen.name]){ if (strip) strip.remove(); return; }
    if (!strip){ strip = el('div','eqlive'); tile.appendChild(strip); }
    const isLive = !!KIT_LIVE[P.k];
    const n = isLive ? CLOCK.live(chosen.name)[P.k] : BOXF[chosen.name][P.k];
    const known = isLive || CLOCK.over;
    strip.className = 'eqlive' + (known && n > 0 ? ' hot' : '');
    strip.innerHTML = known
      ? '<b>' + n + '</b> ' + P.cat.toLowerCase() + ' tonight' +
        (CLOCK.over ? '<span class="fin">FINAL</span>' : '<span class="fin">LIVE</span>')
      : '<b>&nbsp;</b> ' + P.cat.toLowerCase() + '<span class="fin">AT THE BUZZER</span>';
  });
}
CLOCK.on((kind) => {
  if (kind !== 'tick' && kind !== 'final' && kind !== 'reset') return;
  ultLive();
  /* the caption reads "dressed, and final" only at the buzzer, so it has
     to be rebuilt on the two events that move it, and never on a tick */
  if (kind !== 'tick') drawCarl();
});

/* ══ GAME 2: BEAT STORMY ════════════════════════════════════════
   This used to compare a projection against a projection, which means
   it could be "won" sitting on a sofa in July with no hockey being
   played. It is now what it always should have been: Stormy ices five
   before the puck drops, you ice five out of the men he left, and the
   real box score decides the six categories at the final buzzer.

   Stormy is the Citrus AI GM and he picks like a GM: the two best
   forwards available, a checking centre, and a pair that blocks. He
   deliberately leaves Auston Matthews on the board, which is the whole
   lesson of the game, because the fan who grabs Matthews and stacks
   scoring loses hits, blocks and takeaways and finishes 2-4.

   Verified by exhaustive search over every legal fan lineup out of the
   twelve he leaves:

       336 lineups.  fan WINS 36.0%   DRAWS 17.0%   LOSES 47.0%
       exactly one of them takes all six categories

   The board shows season rates before the lock and real numbers after,
   because a board showing tonight's totals before you pick is not a
   game, it is an answer key.                                        */
const HCATS = [
  {k:'g',  l:'Goals'},  {k:'a',  l:'Assists'}, {k:'sog',l:'Shots'},
  {k:'hit',l:'Hits'},   {k:'blk',l:'Blocks'},  {k:'tk', l:'Takeaways'},
];
const H_LIVE = {g:1, a:1, sog:1};        // provable before the buzzer
const DRESSED = BOX_L.filter(r => SEASON[r.name]);
const isD  = p => p.pos === 'D';
const sProj = p => HCATS.reduce((s,c) => s + perGame(p.name, c.k) * (SC[c.k] || 0), 0);

const STORMY_FIVE = ['John Tavares','William Nylander','Jacob Quillan',
                     'Brandon Carlo','Morgan Rielly']
  .map(n => DRESSED.find(p => p.name === n)).filter(Boolean);
const POOL = DRESSED.filter(p => !STORMY_FIVE.includes(p));
const P_F  = POOL.filter(p => !isD(p)).sort((a,b) => sProj(b) - sProj(a));
const P_D  = POOL.filter(isD).sort((a,b) => sProj(b) - sProj(a));
const LEAD = {}; HCATS.forEach(c => { LEAD[c.k] = Math.max(...POOL.map(p => perGame(p.name, c.k))); });

let five = [], sLocked = false;
const nF = () => five.filter(p => !isD(p)).length;
const nD = () => five.filter(isD).length;
const room = p => !sLocked && (isD(p) ? nD() < 2 : nF() < 3);
/* what a side has actually done tonight: live where the feed proves it,
   final where only the box score does, null while it is still unknown */
const sVal = (side, k) => {
  if (H_LIVE[k]) return side.reduce((s,p) => s + CLOCK.live(p.name)[k], 0);
  return CLOCK.over ? side.reduce((s,p) => s + p[k], 0) : null;
};
const scoreLine = () => { let w = 0, l = 0, open = 0;
  HCATS.forEach(c => {
    const m = sVal(five, c.k), s = sVal(STORMY_FIVE, c.k);
    if (m === null || !five.length){ open++; return; }
    if (m > s) w++; else if (m < s) l++;
  });
  return {w, l, open}; };

function lineCard(arr, n, label){
  return Array.from({length:n}, (_, i) => { const p = arr[i];
    return '<div class="clue"><span>'+label+'</span><b>'+(p ? p.name : '-')+'</b>'+
      '<span class="fp">'+(p ? perGame(p.name,'g').toFixed(2)+'G' : '')+'</span></div>'; }).join('');
}

function drawStormy(){
  (function(){ const f = $('#stormyFace');
    if (f && !f.innerHTML) f.innerHTML = mascotImg('stormy', 44); })();
  (function(){ const m = $('#yourMark');
    if (m && !m.innerHTML) m.innerHTML = leafSVG(20, '#FFFFFF'); })();
  const F = five.filter(p => !isD(p)), D = five.filter(isD);
  $('#yourPicks').innerHTML = lineCard(F,3,'Forward') + lineCard(D,2,'Defence');
  if (sLocked){
    const sf = STORMY_FIVE.filter(p=>!isD(p)), sd = STORMY_FIVE.filter(isD);
    $('#stormyPicks').innerHTML = lineCard(sf,3,'Forward') + lineCard(sd,2,'Defence');
    [...document.querySelectorAll('#stormyPicks .clue')].forEach((r,i)=>{
      r.classList.add('flipin'); r.style.animationDelay = (CALM?0:i*0.16)+'s'; });
  } else {
    $('#stormyPicks').innerHTML = ['Forward','Forward','Forward','Defence','Defence'].map(l =>
      '<div class="clue mystery"><span>'+l+'</span><b>?</b><span class="fp"></span></div>').join('');
  }
  const fpts = side => side.reduce((s,p) => s + HCATS.reduce((t,c) => {
    const v = H_LIVE[c.k] ? CLOCK.live(p.name)[c.k] : (CLOCK.over ? p[c.k] : 0);
    return t + v * (SC[c.k]||0); }, 0), 0);
  $('#yourTot').textContent   = five.length ? fpts(five).toFixed(2) : '-';
  $('#stormyTot').textContent = sLocked ? fpts(STORMY_FIVE).toFixed(2) : '-';

  const {w,l,open} = scoreLine();
  const cc = $('#catCard');
  if (cc) cc.style.display = five.length === 5 ? '' : 'none';
  $('#catTable').innerHTML = HCATS.map((c,i) => {
    const m = five.length ? sVal(five, c.k) : null;
    const s = sLocked ? sVal(STORMY_FIVE, c.k) : null;
    const pend = m === null || s === null;
    const res = (!sLocked || pend) ? (sLocked ? '<span class="chip">at the buzzer</span>' : '')
              : m > s ? '<span class="chip win">WIN</span>'
              : m < s ? '<span class="chip lose">LOSS</span>' : '<span class="chip">TIED</span>';
    const tot = (m||0) + (s||0);
    const bar = (m === null || s === null) ? ''
      : '<div class="cbar"><i class="me" style="width:'+(tot?100*m/tot:0)+'%"></i>'+
        '<i class="him" style="width:'+(tot?100*s/tot:0)+'%"></i></div>';
    return '<tr>'+
      '<td class="bld">'+c.l+(H_LIVE[c.k]?'':' <em class="pend">buzzer</em>')+'</td>'+
      '<td class="tot">'+(m === null ? '-' : m)+'</td>'+
      '<td class="bar">'+bar+'</td>'+
      '<td class="tot">'+(s === null ? (sLocked?'-':'?') : s)+'</td>'+
      '<td style="text-align:center">'+res+'</td></tr>';
  }).join('');
  $('#catScore').textContent = sLocked ? (open ? w+' - '+l+' so far' : w+' - '+l)
                                       : (five.length ? five.length+' iced' : '0 - 0');

  const rows = (arr, host) => {
    const box = $(host); if (!box) return; box.innerHTML = '';
    arr.forEach(p => {
      const on = five.includes(p), ok = on || room(p);
      const r = el('div','brow'+(on?' on':'')+(ok&&!sLocked?' live':'')+(!ok?' off':''));
      r.innerHTML = '<span class="bn"><span class="bnm">'+faceOf(p.name, p.num, 26)+
        '<span class="pc '+p.pos+'">'+p.pos+'</span>'+p.name+'</span>'+
        '<i class="bsl">'+(SEASON[p.name] ? SEASON[p.name].gp+' GP this season' : '')+'</i></span>' +
        HCATS.map(c => {
          const shown = sLocked && (H_LIVE[c.k] || CLOCK.over)
            ? (H_LIVE[c.k] ? CLOCK.live(p.name)[c.k] : p[c.k])
            : perGame(p.name, c.k).toFixed(2);
          const top = !sLocked && perGame(p.name, c.k) === LEAD[c.k];
          return '<span class="bv'+(top?' top':'')+'"><i>'+c.k.toUpperCase()+'</i>'+shown+'</span>';
        }).join('');
      if (!sLocked && ok) r.onclick = () => {
        if (on) five = five.filter(x => x !== p); else { five.push(p); Snd.pick(); }
        drawStormy();
      };
      box.appendChild(r);
    });
  };
  rows(P_F, '#poolF'); rows(P_D, '#poolD');
  const st = $('#slotState');
  if (st) st.textContent = nF()+'/3 forwards · '+nD()+'/2 defence';
  const go = $('#stormyGo');
  if (go){ go.disabled = five.length !== 5 || sLocked;
           go.textContent = sLocked ? (CLOCK.over ? 'Settled' : 'Locked, watching') : 'Lock it in'; }
  const hint = $('#stormyHint');
  if (hint) hint.innerHTML = sLocked
    ? (CLOCK.over ? 'Settled.' : BOX_ONLY_NOTE)
    : 'iced. Tonight\'s numbers appear once you lock.';
  if (CLOCK.over && sLocked) stormyFinal();
}

function stormyLock(){
  if (sLocked || five.length !== 5) return;
  sLocked = true; Snd.ding && Snd.ding(); drawStormy();
  if (!CLOCK.running && !CLOCK.over) CLOCK.start();
}
function stormyFinal(){
  if ($('#sFinal')) return;
  const {w,l} = scoreLine();
  const drew = w === l, won = w > l;
  const pts = won ? 120 : drew ? 30 : 0;
  if (pts) award(pts, 'Beat Stormy · ' + w + '-' + l);
  const card = el('div','endcard sfin'); card.id = 'sFinal';
  /* The one moment in the build where a character earns a full-size render:
     the man you just played reacting to the result. stormy_win is HIS win,
     so it shows when he beat you. A draw gets the neutral cut-out, because
     three-three is not a face either way. */
  const face = ART[won ? 'stormy_loss' : drew ? 'cut_stormy' : 'stormy_win'];
  card.innerHTML = (face ? '<img class="sface" src="' + face.src + '" alt="">' : '') +
    '<div class="eyebrow">Full time</div><h3>' +
    (won ? 'You beat him, ' + w + '-' + l : drew ? 'Drawn ' + w + '-' + l : 'Stormy takes it ' + l + '-' + w) +
    '</h3><div class="endrow"><div><b>' + w + '</b><span>categor' + (w===1?'y':'ies') + ' won</span></div>' +
    '<div><b>' + l + '</b><span>categor' + (l===1?'y':'ies') + ' lost</span></div>' +
    '<div><b>' + pts + '</b><span>points</span></div></div>' +
    '<p class="endnote">' + (drew
      ? 'Three-three is a draw, not a win. That is the whole game.'
      : won ? 'Out of the 336 legal lineups he left you, 36.0% get there.'
            : 'He left Matthews on the board on purpose. 36.0% of the lineups he left still beat him.') +
    '</p><button class="act" id="sAgain">Ice another five</button>';
  $('#stormyVerdict').innerHTML = ''; $('#stormyVerdict').appendChild(card);
  $('#sAgain').onclick = () => { five = []; sLocked = false;
    const f = $('#sFinal'); if (f) f.remove(); CLOCK.reset(); drawStormy(); };
  if (won){ confetti(); Snd.win && Snd.win(); }
}
CLOCK.on(kind => {
  if (kind === 'reset'){ const f = $('#sFinal'); if (f) f.remove(); }
  /* while the fan is still icing a lineup the board must hold still; once it
     is locked there is nothing to tap and a full redraw is safe */
  if (kind === 'tick' && !sLocked) return;
  if (kind === 'tick' || kind === 'final' || kind === 'reset') drawStormy();
});

const HL_SK=[{k:'g',l:'Goals'},{k:'a',l:'Assists'},{k:'sog',l:'Shots'},{k:'hit',l:'Hits'},
             {k:'blk',l:'Blocks'},{k:'pim',l:'Penalty minutes'},{k:'p',l:'Points'}];
const HL_GK=[{k:'w',l:'Wins'},{k:'sv',l:'Saves'},{k:'so',l:'Shutouts'}];

/* Context without the answer. Points, goals and assists move as one, so a
   round on any of them shows none of them. Games played is always safe and
   is the fact that actually decides most of these rounds; the xG grade is a
   rate, so it informs the read without settling it -- which is the edge a
   fan who knows the team is supposed to have. */
/* "1 goals" reads as a bug even when the number is right */
const plural = (label, n) => {
  const l = label.toLowerCase();
  if (n === 1){
    if (l === 'penalty minutes') return 'penalty minute';
    if (l === 'shutouts') return 'shutout';
    return l.replace(/s$/,'');
  }
  return l;
};
const HL_TIED = {g:1, a:1, p:1};
const HL_GKT  = {w:1, sv:1, so:1};
function hlLine(p, k){
  const s = SEASON[p.name] || p, bits = ['<span class="pc '+p.pos+'">'+p.pos+'</span>'];
  if (p.num) bits.push('<em class="jnum">#'+p.num+'</em>');
  bits.push('<em>'+s.gp+'</em> GP');
  if (!s.gk){
    const banned = HL_TIED[k] ? HL_TIED : {[k]:1};
    [['sog','shots'],['hit','hits'],['blk','blocks'],['pim','PIM']].forEach(([kk,lab]) => {
      if (!banned[kk] && kk !== k && bits.length < 4) bits.push('<em>'+s[kk]+'</em> '+lab);
    });
    if (s.xgr && GRADE[s.xgr]) bits.push('<span class="sc '+GRADE[s.xgr]+'">'+s.xgr+'</span>');
  } else if (!HL_GKT[k] && s.svp) bits.push('<em>'+(s.svp*100).toFixed(1)+'</em> SV%');
  return bits.join(' ');
}

/* ══ GAME 4: GUESS THE LEAF ═════════════════════════════════════ */
const CLUE_SK=[p=>['Position',p.pos],p=>['Games played',p.gp],p=>['Goals',p.g],
               p=>['Assists',p.a],p=>['Shots on goal',p.sog],p=>['Hits',p.hit],p=>['Jersey','#'+p.num]];
const CLUE_GK=[p=>['Position','Goaltender'],p=>['Games played',p.gp],p=>['Wins',p.w],
               p=>['Save %',p.svp!=null?p.svp.toFixed(3):'-'],p=>['Saves',p.sv],
               p=>['Shutouts',p.so],p=>['Jersey','#'+p.num]];
const LOCK_SVG = '<svg viewBox="0 0 24 24" aria-hidden="true" class="lockg">' +
  '<rect x="4.5" y="10" width="15" height="10.5" rx="2.6"/>' +
  '<path d="M8.3 10V7.4a3.7 3.7 0 0 1 7.4 0V10"/></svg>';
let gT=null,gN=0,gScore=0,gLock=false,gClues=CLUE_SK;
let gHinted=false;
/* This game used to run for ever: every answer queued the next player on a
   timer with no end and no total. Five rounds and a card, so it finishes. */
const G_ROUNDS = 5;
let gRound = 0, gRight = 0, gPlayed = [];
function gNew(){
  if (gRound >= G_ROUNDS){ gEnd(); return; }
  gRound++;
  const rc = $('#gRound'); if (rc) rc.textContent = gRound + ' of ' + G_ROUNDS;
  gDots(); gSoFar();
  gLock=false; gN=1; gHinted=false; $('#gMsg').textContent='';
  gT=rand(R); gClues = gT.gk?CLUE_GK:CLUE_SK;
  $('#gOpts').innerHTML=''; $('#gList').innerHTML=''; $('#gIn').value='';
  $('#gMore').disabled=false; $('#gHint').disabled=false;
  gDraw();
}
/* typing beats multiple choice: naming him cold is the game. The four-name
   hint still exists, but it costs you. */
function gWorth(){ return Math.max(10, 60 - gN*10 - (gHinted?15:0)); }
function gSearch(q){
  const list=$('#gList'); list.innerHTML='';
  const t=q.trim().toLowerCase(); if(t.length<2||gLock) return;
  R.filter(p=>p.name.toLowerCase().includes(t)).slice(0,5).forEach(p=>{
    const b=el('button'); b.innerHTML=p.name+'<small>'+(p.gk?'G':p.pos)+' &middot; #'+p.num+'</small>';
    b.onclick=()=>gPick(p,null); list.appendChild(b);
  });
}
function gHint(){
  if (gLock||gHinted) return; gHinted=true; $('#gHint').disabled=true;
  const wrong = shuffle(R.filter(p=>p!==gT && p.gk===gT.gk)).slice(0,3);
  $('#gOpts').innerHTML='';
  shuffle([gT,...wrong]).forEach(p=>{
    const b=el('button','opt',p.name); b.onclick=()=>gPick(p,b); $('#gOpts').appendChild(b);
  });
  gDraw();
}
function gDraw(){
  /* Seven slots, always. Showing only the clues taken so far left the page
     three-quarters empty and gave the fan no sense of what he was spending
     down. A locked slot is information: it is the shape of the game. */
  $('#gClues').innerHTML = '<div class="clues">'+gClues.map((f,i)=>{
    if (i < gN){
      const c=f(gT), fresh = i === gN-1;
      return '<div class="clue'+(fresh?' dealin':'')+'"><div class="ci">'+(i+1)+'</div>'+
             '<div><span>'+c[0]+'</span><b>'+c[1]+'</b></div></div>';
    }
    const cost = i === gN ? '&minus;10 to open' : 'locked';
    /* This was ART.state_locked, an illustrated padlock, drawn into a 30px
       chip. An illustration at 30px is a brown smudge; six of them down the
       board looked like a rendering fault. Three shapes of SVG say locked
       at any size, which is the whole reason icons exist. */
    return '<div class="clue lk"><div class="ci">' + LOCK_SVG +
      '</div><div><span>Clue '+(i+1)+'</span><b>'+cost+'</b></div></div>';
  }).join('')+'</div>';
  rollNum($('#gWorth'), gWorth(), 0, 300);
}
function gPick(p,btn){
  if (gLock) return; gLock=true;
  $('#gMore').disabled = true; $('#gHint').disabled = true; $('#gList').innerHTML='';
  const w=gWorth();
  const ok = p===gT;
  if (ok){ Snd.ding(); gScore+=w; if(btn) btn.classList.add('right'); award(w,'Guess the Leaf · '+gT.name);
    $('#gMsg').innerHTML='<span class="up">Correct, '+gT.name+'. +'+w+'</span>'; }
  else { hitstop(()=>{ shakeCard($('#gMsg')); Snd.thud(); }); if(btn) btn.classList.add('wrong');
    [...document.querySelectorAll('.opt')].filter(b=>b.textContent===gT.name).forEach(b=>b.classList.add('right'));
    $('#gMsg').innerHTML='<span class="dn">'+(p?p.name+' is a real Leaf, but no. It was '+gT.name+'.':'It was '+gT.name+'.')+'</span>'; }
  quip('guess', ok, $('#gMsg'));
  $('#gScore').textContent=gScore;
  gPlayed.push({ name: gT.name, ok: ok, worth: ok ? w : 0 });
  if (ok) gRight++;
  gDots(); gSoFar();
  if (gRound >= G_ROUNDS) setTimeout(gEnd, 2000); else setTimeout(gNew, 2300);
}

function gDots(){
  const box = $('#gDots'); if (!box) return;
  box.innerHTML = Array.from({length:G_ROUNDS}, (_, i) => {
    const r = gPlayed[i];
    return '<i class="' + (r ? (r.ok ? 'hit' : 'miss') : (i === gRound-1 ? 'now' : '')) + '"></i>';
  }).join('');
}
function gSoFar(){
  const box = $('#gSoFar'); if (!box) return;
  box.innerHTML = gPlayed.length
    ? '<b>This round so far</b>' + gPlayed.map(r =>
        '<span>' + r.name + '<em>' + (r.ok ? '+' + r.worth : 'missed') + '</em></span>').join('')
    : '';
}
function gEnd(){
  if ($('#gFinal')) return;
  const card = el('div','endcard'); card.id = 'gFinal';
  card.innerHTML = '<div class="eyebrow">Round over</div><h3>' + gRight + ' of ' + G_ROUNDS + '</h3>' +
    '<div class="endrow"><div><b>' + gRight + '</b><span>named</span></div>' +
    '<div><b>' + gScore + '</b><span>points</span></div></div>' +
    '<p class="endnote">' + gPlayed.map(p => (p.ok ? '' : '') + p.name).join(', ') + '.</p>' +
    '<button class="act" id="gAgain">Five more</button>';
  $('#gMsg').innerHTML = ''; $('#gMsg').appendChild(card);
  $('#gOpts').innerHTML = ''; $('#gList').innerHTML = '';
  const mb = $('#gMore'), hb = $('#gHint'), ib = $('#gIn');
  if (mb) mb.disabled = true; if (hb) hb.disabled = true; if (ib) ib.disabled = true;
  $('#gAgain').onclick = () => { gRound = 0; gRight = 0; gPlayed = []; gScore = 0;
    const f = $('#gFinal'); if (f) f.remove(); $('#gMsg').innerHTML = '';
    if (ib) ib.disabled = false; gNew(); };
  if (gRight >= 4){ confetti(); Snd.win && Snd.win(); }
}

/* ══ GAME 3: WHO GOES OFF ═══════════════════════════════════════
   Six head-to-heads. No numbers to read, just: which of these two
   Leafs finishes tonight with more. The pairs are built so the two
   are within a third of each other on the season, because a pair
   nobody would think twice about is not a question.               */
function h2hSlate(){
  const cand = [];
  SLATE_CATS.forEach(c => {
    for (let i = 0; i < SLATE.length; i++) for (let j = i+1; j < SLATE.length; j++){
      const A = SLATE[i], B = SLATE[j];
      if (A[c.k] === B[c.k]) return_continue: { if (A[c.k] === B[c.k]) continue; }
      const ra = perGame(A.name, c.k), rb = perGame(B.name, c.k);
      if (ra < .15 || rb < .15) continue;
      const gap = Math.abs(ra - rb) / Math.max(ra, rb);
      if (gap > .34) continue;
      /* something has to actually happen, or "0 versus 1 block" is the question */
      if (Math.max(A[c.k], B[c.k]) < 2) continue;
      cand.push({ a:A, b:B, c, ra, rb, gap,
                  upset: (ra > rb) !== (A[c.k] > B[c.k]),
                  /* close on the season AND names the building knows */
                  rank: gap - (A.toi + B.toi) / 420 });
    }
  });
  cand.sort((x, y) => x.rank - y.rank);
  const out = [], used = new Set(), byCat = {};
  for (const x of cand){
    if (used.has(x.a.name) || used.has(x.b.name)) continue;
    if ((byCat[x.c.k] || 0) >= 2) continue;
    used.add(x.a.name); used.add(x.b.name); byCat[x.c.k] = (byCat[x.c.k]||0) + 1;
    out.push(x); if (out.length === 6) break;
  }
  return out;
}
const H2H = h2hSlate();
let h2hPick = {}, h2hLocked = false;

function h2hCount(){
  const n = Object.keys(h2hPick).length;
  const s = $('#hlStreak'); if (s) s.textContent = n + ' of 6';
  const go = $('#hlGo');
  if (go){ go.disabled = n < 6 || h2hLocked;
           go.textContent = h2hLocked ? (CLOCK.over ? 'Settled' : 'Locked, watching') : 'Lock the slate'; }
}
function drawH2H(){
  const box = $('#hlCards'); if (!box) return;
  const st = slateStatus();
  box.innerHTML = '';
  H2H.forEach((m, i) => {
    const av = liveVal(m.a.name, m.c.k), bv = liveVal(m.b.name, m.c.k);
    const known = av !== null;
    const winner = known ? (m.a[m.c.k] > m.b[m.c.k] ? 'a' : 'b') : null;
    const settled = CLOCK.over;
    const row = el('div', 'vsrow' + (h2hLocked ? ' locked' : '') +
      (settled && h2hPick[i] ? (h2hPick[i] === winner ? ' hit' : ' miss') : ''));
    row.innerHTML =
      '<div class="h2hq"><span class="h2hn">' + (i+1) + '</span>' +
      '<span class="h2hask">Who finishes with more <b>' + m.c.l + '</b>?</span>' +
      (known ? '' : '<span class="h2hsettle">settles at the buzzer</span>') + '</div>' +
      ['a','b'].map(side => {
        const p = m[side], v = side === 'a' ? av : bv;
        const on = h2hPick[i] === side;
        return '<button class="h2hp' + (on ? ' on' : '') +
          (settled && winner === side ? ' won' : '') + '" data-i="' + i + '" data-s="' + side + '">' +
          '<span class="h2hj">' + faceOf(p.name, p.num, 30) + '</span>' +
          '<span class="h2hnm">' + p.name + '</span>' +
          '<span class="h2hr">' + perGame(p.name, m.c.k).toFixed(2) + ' a game this season</span>' +
          '<span class="h2hv">' + (v === null ? '' : v) + '</span></button>';
      }).join('');
    box.appendChild(row);
  });
  /* Toggle the classes on the buttons that are already on screen. Rebuilding
     the list on every tap detaches the node the fan just pressed, which loses
     the tap on a phone and flickers on a desktop. Same bug Pick'em had. */
  box.querySelectorAll('.h2hp').forEach((btn, k) => {
    const m = H2H[Math.floor(k/2)];
    btn._live = { p: m[k % 2 === 0 ? 'a' : 'b'], k: m.c.k };
  });
  box.querySelectorAll('.h2hp').forEach(btn => btn.onclick = () => {
    if (h2hLocked) return;
    const i = +btn.dataset.i;
    h2hPick[i] = btn.dataset.s;
    btn.parentElement.querySelectorAll('.h2hp').forEach(o =>
      o.classList.toggle('on', o.dataset.s === h2hPick[i]));
    Snd.pick && Snd.pick(); h2hCount();
  });
  h2hCount();
  const hint = $('#hlHint');
  if (hint) hint.innerHTML = h2hLocked
    ? (CLOCK.over ? 'Settled.' : BOX_ONLY_NOTE)
    : st === 'pre' ? 'picked, then lock' : 'picked. The game has started.';
  if (CLOCK.over && h2hLocked) h2hFinal();
}
/* Rebuilding all six cards on every clock tick detaches the button the fan
   has their thumb on, which makes the game unusable during the live game it
   was built for. Tick updates the numbers only. */
function h2hValues(){
  const box = $('#hlCards'); if (!box) return;
  box.querySelectorAll('.h2hp').forEach(btn => {
    const L = btn._live; if (!L) return;
    const v = liveVal(L.p.name, L.k);
    const cell = btn.querySelector('.h2hv');
    if (cell) cell.textContent = v === null ? '' : v;
  });
}
function h2hLock(){
  if (h2hLocked || Object.keys(h2hPick).length < 6) return;
  h2hLocked = true; Snd.ding && Snd.ding(); drawH2H();
  if (!CLOCK.running && !CLOCK.over) CLOCK.start();
}
function h2hFinal(){
  if ($('#hlFinal')) return;
  let hits = 0;
  H2H.forEach((m, i) => { const w = m.a[m.c.k] > m.b[m.c.k] ? 'a' : 'b'; if (h2hPick[i] === w) hits++; });
  const pts = PAYOUT[hits];
  if (pts) award(pts, 'Who Goes Off · ' + hits + ' of 6');
  const card = el('div','endcard'); card.id = 'hlFinal';
  card.innerHTML = '<div class="eyebrow">Full time</div><h3>' + hits + ' of 6</h3>' +
    '<div class="endrow"><div><b>' + hits + '</b><span>called right</span></div>' +
    '<div><b>' + pts + '</b><span>points</span></div>' +
    '<div><b>6</b><span>head to heads</span></div></div>' +
    '<p class="endnote">' + (hits === 6 ? 'A clean slate. Nobody in the room beat that.'
      : hits >= 4 ? 'A winning slate.' : 'The board resets at the next puck drop.') + '</p>' +
    '<button class="act" id="hlAgain">Play it again</button>';
  $('#hlMsg').appendChild(card);
  $('#hlAgain').onclick = () => { h2hPick = {}; h2hLocked = false;
    const f = $('#hlFinal'); if (f) f.remove(); CLOCK.reset(); drawH2H(); };
  if (hits >= 4){ confetti(); Snd.win && Snd.win(); }
}

/* ══ GAME 5: HEAT CHECK ═════════════════════════════════════════
   Was "Luck or Skill", which asked a fan to decide whether a Leaf's
   goals were luck. In front of the club that game says their players
   are fortunate rather than good, and it was also a quiz about our
   own model. Same skill, pointed forward instead: six lines on
   tonight, each one set at that player's own season rate.          */
function heatSlate(){
  const cand = [];
  SLATE.forEach(r => SLATE_CATS.forEach(c => {
    const ln = lineFor(r.name, c.k), v = r[c.k];
    const rate = perGame(r.name, c.k);
    if (!rate || rate < .12) return;
    cand.push({ r, c, ln, v, over: v > ln, m: Math.abs(v - ln) });
  }));
  cand.sort((x, y) => (x.m - y.m) || (y.r.toi - x.r.toi));
  const out = [], seen = new Set(); let o = 0, u = 0;
  for (const x of cand){
    if (seen.has(x.r.name)) continue;
    if (x.over ? o >= 3 : u >= 3) continue;
    seen.add(x.r.name); x.over ? o++ : u++; out.push(x);
    if (out.length === 6) break;
  }
  return out.sort((x, y) => y.r.toi - x.r.toi);
}
const HEAT = heatSlate();
let heatPick = {}, heatLocked = false;

function heatCount(){
  const n = Object.keys(heatPick).length;
  const s = $('#lkScore'); if (s) s.textContent = n + ' of 6';
  const go = $('#lkGo');
  if (go){ go.disabled = n < 6 || heatLocked;
           go.textContent = heatLocked ? (CLOCK.over ? 'Settled' : 'Locked, watching') : 'Lock the card'; }
}
function drawHeat(){
  const box = $('#lkCard'); if (!box) return;
  box.className = 'heatlist';
  box.innerHTML = HEAT.map((h, i) => {
    const v = liveVal(h.r.name, h.c.k), known = v !== null, settled = CLOCK.over;
    const truth = h.over ? 'over' : 'under';
    const mine = heatPick[i];
    return '<div class="heat' + (settled && mine ? (mine === truth ? ' hit' : ' miss') : '') + '">' +
      '<div class="heatwho"><span class="heatj">' + faceOf(h.r.name, h.r.num, 34) + '</span>' +
      '<span><b>' + h.r.name + '</b>' +
      '<em>' + perGame(h.r.name, h.c.k).toFixed(2) + ' ' + h.c.l + ' a game this season</em></span></div>' +
      '<div class="heatline"><span class="hl2">' + h.ln.toFixed(1) + '</span>' +
      '<span class="hlc">' + h.c.l + '</span></div>' +
      '<div class="heatbtns">' +
        ['over','under'].map(k => '<button class="heatb' + (mine === k ? ' on' : '') +
          (settled && truth === k ? ' won' : '') + '" data-i="' + i + '" data-k="' + k + '">' +
          (k === 'over' ? 'Over' : 'Under') + '</button>').join('') + '</div>' +
      '<div class="heatv">' + (known ? '<b>' + v + '</b><span>tonight</span>'
                                     : '<span class="pend">at the buzzer</span>') + '</div></div>';
  }).join('');
  box.querySelectorAll('.heat').forEach((row, i) => { row._live = HEAT[i]; });
  box.querySelectorAll('.heatb').forEach(btn => btn.onclick = () => {
    if (heatLocked) return;
    const i = +btn.dataset.i;
    heatPick[i] = btn.dataset.k;
    btn.parentElement.querySelectorAll('.heatb').forEach(o =>
      o.classList.toggle('on', o.dataset.k === heatPick[i]));
    Snd.pick && Snd.pick(); heatCount();
  });
  heatCount();
  const hint = $('#lkHint');
  if (hint) hint.innerHTML = heatLocked
    ? (CLOCK.over ? 'Settled.' : BOX_ONLY_NOTE)
    : 'picked, then lock the card';
  if (CLOCK.over && heatLocked) heatFinal();
}
function heatValues(){
  const box = $('#lkCard'); if (!box) return;
  box.querySelectorAll('.heat').forEach(row => {
    const h = row._live; if (!h) return;
    const v = liveVal(h.r.name, h.c.k);
    const cell = row.querySelector('.heatv');
    if (cell && v !== null) cell.innerHTML = '<b>' + v + '</b><span>tonight</span>';
  });
}
function heatLock(){
  if (heatLocked || Object.keys(heatPick).length < 6) return;
  heatLocked = true; Snd.ding && Snd.ding(); drawHeat();
  if (!CLOCK.running && !CLOCK.over) CLOCK.start();
}
function heatFinal(){
  if ($('#lkFinal')) return;
  let hits = 0;
  HEAT.forEach((h, i) => { if (heatPick[i] === (h.over ? 'over' : 'under')) hits++; });
  const pts = PAYOUT[hits];
  if (pts) award(pts, 'Heat Check · ' + hits + ' of 6');
  const card = el('div','endcard'); card.id = 'lkFinal';
  card.innerHTML = '<div class="eyebrow">Full time</div><h3>' + hits + ' of 6</h3>' +
    '<div class="endrow"><div><b>' + hits + '</b><span>lines hit</span></div>' +
    '<div><b>' + pts + '</b><span>points</span></div></div>' +
    '<p class="endnote">' + (hits === 6 ? 'Perfect card.' :
      hits >= 4 ? 'A winning card.' : 'New lines at the next puck drop.') + '</p>' +
    '<button class="act" id="lkAgain">Play it again</button>';
  $('#lkReveal').innerHTML = ''; $('#lkReveal').appendChild(card);
  $('#lkAgain').onclick = () => { heatPick = {}; heatLocked = false;
    $('#lkReveal').innerHTML = ''; CLOCK.reset(); drawHeat(); };
  if (hits >= 4){ confetti(); Snd.win && Snd.win(); }
}

/* ══ GAME 6: RANK 'EM ═══════════════════════════════════════════
   Same idea, forward: order four Leafs by where they finish tonight. */
const RK_CATS = SLATE_CATS;
let rkSet = [], rkCat = null, rkOrder = [], rkLock = false, rkScore = 0, rkShown = '';
function rkNew(){
  rkLock = false; rkOrder = []; $('#rkMsg').textContent = '';
  const f = $('#rkFinal'); if (f) f.remove();
  rkCat = rand(RK_CATS.filter(c => c.k !== 'tk'));
  const byRate = [...SLATE].sort((a,b) => perGame(b.name, rkCat.k) - perGame(a.name, rkCat.k));
  const top = byRate.slice(0, 8);
  let guard = 0;
  do { rkSet = shuffle(top).slice(0,4); guard++; }
  while (new Set(rkSet.map(p => p[rkCat.k])).size < 4 && guard < 80);
  if (new Set(rkSet.map(p => p[rkCat.k])).size < 4){
    const seen = new Set(); rkSet = [];
    for (const p of byRate){ if (seen.has(p[rkCat.k])) continue; seen.add(p[rkCat.k]); rkSet.push(p); if (rkSet.length === 4) break; }
  }
  /* This used to be a whole card holding one sentence that restated the
     subtitle above it. The stat is the game's one parameter, so it sits in
     the header chips where the other parameters already are. */
  $('#rkPrompt').textContent = 'Ranking by ' + rkCat.l;
  /* Two of the four categories exist in the shot feed and two only exist
     in the box score, so half the time this page can show a race moving
     and half the time it genuinely cannot. Say which before the fan
     picks, rather than letting them lock and then wonder why nothing
     moves for an hour. */
  const s = $('#rkSettle');
  if (s) s.textContent = KIT_LIVE[rkCat.k] ? 'Live from the feed' : 'Settles at the buzzer';
  rkShown = '';
  rkDraw();
}
/* Use prow, the row every other game already uses. The hand-rolled version
   here rendered a bare <button>, and a button does not inherit colour, so the
   name came out as UA black on navy at 1.43:1. Reusing the component is also
   how the sweater, the position chip and the value bar stay identical to the
   rest of the build. */
const NTH = ['1st','2nd','3rd','4th'];
/* The bar every other game draws and this one did not. rkRow called prow
   without frac, so the middle 1,100px of a four-row page was empty and
   the page measured as the thinnest in the build. The bar is the race:
   each man against whoever is leading the four right now. */
function rkShare(p, get){
  const vals = rkSet.map(get).filter(v => v !== null && isFinite(v));
  const max = vals.length ? Math.max(...vals) : 0;
  const v = get(p);
  return (v === null || !max) ? 0 : v / max;
}
const rkFrac     = p => rkShare(p, x => liveVal(x.name, rkCat.k));
const rkRateFrac = p => rkShare(p, x => perGame(x.name, rkCat.k));
/* Shots and points come off the shot feed. Hits and blocks exist only in the
   box score, so on those two of the four categories there is no number and no
   bar until the buzzer, and the row went straight back to the empty middle
   this page was just fixed for -- half the time.

   The bar is drawn from the man's season rate instead, which is not a
   substitute for tonight's number and is not presented as one: the value
   reads as a rate, the unit says so, and the bar is greyed so it cannot be
   mistaken for a live count. It is also exactly what the fan is ranking on
   before the puck drops, so it is the honest thing to put in front of them. */
function rkRow(p, opts){
  const v = liveVal(p.name, rkCat.k);
  const known = v !== null;
  const rate = perGame(p.name, rkCat.k);
  const r = prow(p, {
    on: opts.on,
    val: known ? v : rate.toFixed(2),
    unit: known ? rkCat.l : 'a game this season',
    frac: known ? rkFrac(p) : rkRateFrac(p),
    line: (opts.n ? '<em class="slotord">' + opts.n + '</em><s>&middot;</s>' : '') +
          (known ? '<em>' + rate.toFixed(2) + '</em> a game this season'
                 : '<em>settles at the buzzer</em>') +
          (opts.extra || '')
  });
  r.className += (known ? '' : ' rkrate') + (opts.cls || '');
  return r;
}
/* The order on screen, and the ONE rule that matters here.

   This used to sort by p[rkCat.k] the moment the fan locked, and that is
   the FINAL box-score number. Lock at 5:00 of the first and the four rows
   re-sorted into the finishing order, numbered 1 to 4, with fifty minutes
   still to play. The game was over before the buzzer and it said so on
   screen. Verified against the feed: Nylander sat second on a live 0 while
   Matthews sat third on a live 1, which is only explicable as the final
   answer leaking.

   Locked and live, the rows now stand in the LIVE order, off the same
   feed the fan can see, with their own call pinned to each man so they
   can watch it drift. Ties hold the fan's own order so the list does not
   jitter between events. Only at the buzzer does the truth decide it. */
function rkStanding(){
  return [...rkSet].sort((a, b) => {
    const va = liveVal(a.name, rkCat.k), vb = liveVal(b.name, rkCat.k);
    if (va === null && vb === null) return rkOrder.indexOf(a) - rkOrder.indexOf(b);
    if (va === null) return 1;
    if (vb === null) return -1;
    return (vb - va) || (rkOrder.indexOf(a) - rkOrder.indexOf(b));
  });
}
function rkDraw(){
  const box = $('#rkOpts'); box.innerHTML = '';
  if (rkLock){
    if (CLOCK.over){
      const truth = [...rkSet].sort((a,b) => b[rkCat.k] - a[rkCat.k]);
      truth.forEach((p, slot) => {
        const ok = rkOrder[slot] === p;
        box.appendChild(rkRow(p, { n: slot+1, cls: ok ? ' ok' : ' bad',
          extra: ok ? ' <s>&middot;</s><em style="color:var(--good)">you had him here</em>'
                    : ' <s>&middot;</s><em style="color:var(--bad)">you had ' + last(rkOrder[slot].name) + '</em>' }));
      });
      return;
    }
    rkStanding().forEach((p, slot) => {
      box.appendChild(rkRow(p, { n: slot+1,
        extra: ' <s>&middot;</s><em>you had him ' + NTH[rkOrder.indexOf(p)] + '</em>' }));
    });
    return;
  }
  rkSet.forEach(p => {
    const idx = rkOrder.indexOf(p);
    const r = rkRow(p, { on: idx >= 0, n: idx >= 0 ? idx+1 : '' });
    r.onclick = () => {
      if (idx >= 0) rkOrder.splice(idx,1); else if (rkOrder.length < 4) rkOrder.push(p);
      rkDraw();
      if (rkOrder.length === 4) rkLockIn();
    };
    box.appendChild(r);
  });
}
/* Numbers in place between events; a full redraw only when the standing
   actually changes hands. Rebuilding four rows on every tick throws away
   the bar's transition and makes a still page look like it is flickering,
   and this build has already shipped one bug from redrawing on a tick. */
function rkValues(){
  if (!rkLock || CLOCK.over) return;
  const order = rkStanding().map(p => p.name).join('|');
  if (order !== rkShown){ rkShown = order; rkDraw(); return; }
  const rows = document.querySelectorAll('#rkOpts .prow');
  rkStanding().forEach((p, i) => {
    const row = rows[i]; if (!row) return;
    const v = liveVal(p.name, rkCat.k);
    if (v === null) return;               // a rate row has nothing live to move
    const b = row.querySelector('.rt b'); if (b) b.textContent = v;
    const bar = row.querySelector('.rt .bar i');
    if (bar) bar.style.width = Math.round(rkFrac(p) * 100) + '%';
  });
}
function rkLockIn(){
  rkLock = true; Snd.ding && Snd.ding(); rkDraw();
  rkShown = rkStanding().map(p => p.name).join('|');
  $('#rkMsg').innerHTML = CLOCK.over ? '' :
    '<span class="sk">Locked. The rows below stand in tonight\u2019s order as it happens. ' +
    'It settles at the final buzzer.</span>';
  if (!CLOCK.running && !CLOCK.over) CLOCK.start();
  if (CLOCK.over) rkFinal();
}
function rkFinal(){
  if ($('#rkFinal')) return;
  const truth = [...rkSet].sort((a,b) => b[rkCat.k] - a[rkCat.k]);
  const hits = rkOrder.filter((p,i) => p === truth[i]).length;
  const pts = hits === 4 ? 60 : hits * 10;
  if (pts) award(pts, "Rank 'Em · " + hits + '/4');
  rkScore += pts; $('#rkScore').textContent = rkScore;
  rkDraw();
  const card = el('div','endcard'); card.id = 'rkFinal';
  card.innerHTML = '<div class="eyebrow">Full time</div><h3>' + hits + ' of 4 in the right slot</h3>' +
    '<div class="endrow"><div><b>' + hits + '</b><span>correct</span></div>' +
    '<div><b>' + pts + '</b><span>points</span></div></div>' +
    '<p class="endnote">Tonight: ' + truth.map(p => last(p.name) + ' ' + p[rkCat.k]).join(', ') + '.</p>' +
    '<button class="act" id="rkAgain">New four</button>';
  $('#rkMsg').innerHTML = ''; $('#rkMsg').appendChild(card);
  $('#rkAgain').onclick = () => { const f = $('#rkFinal'); if (f) f.remove(); rkNew(); };
  if (hits === 4){ confetti(); Snd.win && Snd.win(); } else if (hits) Snd.ding && Snd.ding();
}

(function(){
  const a = $('#hlLadder'), b = $('#lkLadder'), c = $('#rkLadder');
  if (a) a.innerHTML = payRow(PAYOUT, 6);
  if (b) b.innerHTML = payRow(PAYOUT, 6);
  if (c) c.innerHTML = payRow({4:60, 3:30, 2:20, 1:10}, 4);
})();

CLOCK.on(kind => {
  if (kind !== 'tick' && kind !== 'final' && kind !== 'reset') return;
  if (kind === 'tick'){
    /* numbers only. A full redraw here rips the card out from under a thumb. */
    h2hValues(); heatValues();
    if (rkLock) rkValues();
    return;
  }
  if (kind === 'reset') ['#hlFinal','#lkFinal','#rkFinal'].forEach(s => { const n = $(s); if (n) n.remove(); });
  drawH2H(); drawHeat();
  if (rkLock && kind === 'final') rkFinal(); else if (rkLock) rkDraw();
});

/* ══ GAME 7: OPENING NIGHT PICK'EM ══════════════════════════════
   The live-data game. These are the real 2026-27 fixtures out of
   nhl_games -- opening night is 29 September vs Montreal. Cards lock
   and score as the season plays, which is exactly the season-long
   hook a gameday app wants.                                        */
const FANPCT=[71,64,58,66,43,38,47,69,62,74];
let fxPicks={}, fxLocked=false;
function drawFx(){
  const box=$('#fxList'); box.innerHTML='';
  FX.forEach((f,i)=>{
    const opp = f.home ? f.an : f.hn;
    const c = el('div','fxrow'+(fxPicks[i]?' picked':''));
    c.innerHTML =
      '<div class="fxd"><b>'+new Date(f.d+'T12:00:00').toLocaleDateString('en-CA',{month:'short',day:'numeric'})+'</b>'+
        '<span>'+(f.home?'vs':'@')+' '+opp+'</span></div>'+
      '<div class="fxbtns">'+
        '<button class="fxb'+(fxPicks[i]==='W'?' sel':'')+'" data-i="'+i+'" data-v="W">Leafs win</button>'+
        '<button class="fxb'+(fxPicks[i]==='L'?' sel':'')+'" data-i="'+i+'" data-v="L">'+opp+'</button>'+
      '</div>'+
      '<div class="fxcon"><div class="cl"><span>Toronto <b>'+FANPCT[i]+'%</b></span>'+
        '<span><b>'+(100-FANPCT[i])+'%</b> '+opp+'</span></div>'+
        '<div class="cbar"><i style="width:'+FANPCT[i]+'%"></i><i class="b" style="width:'+(100-FANPCT[i])+'%"></i></div></div>'+
      '<div class="fxpct">'+(FANPCT[i]>=60?'Crowd on<br><span>Toronto</span>':FANPCT[i]<=45?'Crowd off<br><span>Toronto</span>':'Split<br><span>room</span>')+'</div>';
    if (!fxLocked) c.querySelectorAll('.fxb').forEach(b=>b.onclick=()=>{
      /* toggle in place. Rebuilding the whole card on every tap destroyed
         the button under the finger and restarted ten animations to change
         one class. */
      fxPicks[b.dataset.i]=b.dataset.v;
      c.classList.add('picked');
      c.querySelectorAll('.fxb').forEach(x=>x.classList.toggle('sel', x===b));
      Snd.pick(); fxCount();
    });
    box.appendChild(c);
  });
  fxCount();
}
function fxCount(){
  const n=Object.keys(fxPicks).length;
  $('#fxCount').textContent = n+' / '+FX.length;
  $('#fxGo').disabled = n<FX.length || fxLocked;
}
function fxLock(){
  fxLocked=true; award(100,"Opening Night card submitted");
  drawFx();
  const rows = document.querySelectorAll('.fxrow');
  rows.forEach((r,i)=>{
    if (CALM) return;
    r.style.opacity='0';
    setTimeout(()=>{ r.style.opacity='';
      r.animate([{opacity:0,transform:'translateX(-8px)'},{opacity:1,transform:'none'}],
        {duration:220, easing:'cubic-bezier(0,0,.2,1)'});
      Snd.tick(i*2);
    }, i*45);
  });
  $('#fxState').innerHTML =
    '<div class="reveal"><div class="cat">Card locked</div>'+
    '<p>Ten picks in. This card scores from <b>29 September</b>, 50 points a correct call, '+
    'and the board updates the morning after every game. That is the hook: a fan who fills '+
    'this in has a reason to open the app on a Tuesday in January.</p></div>';
}

/* ══ GAME 8: BEAT THE BUZZER ════════════════════════════════════
   Sixty seconds, mixed questions. This is the session-length driver:
   it reuses the other engines but rewards volume and nerve.         */
let bzT=null, bzLeft=0, bzScore=0, bzRunning=false, bzQ=null, bzCount=0;
/* what the area holds before the clock starts. ESPN and Yahoo fill a
   pre-game panel with what is coming and how it scores; none of the three
   ever render an empty box. */
function bzIdle(){
  const a = $('#bzArea'); if (!a || bzRunning) return;
  a.innerHTML = '<div class="bzidle">Who had more, name the Leaf, faceoffs won, shot attempts.<br>' +
                'Press start and they come one after another until the buzzer.</div>';
  const st = $('#bzStage'); if (st) st.classList.remove('warn','crit');
  bzStats();
}
let bzBest = 0, bzRight = 0;
function bzStart(){
  if (bzRunning) return;
  bzRunning=true; bzLeft=60; bzScore=0; bzCount=0; bzRight=0;
  $('#bzStart').disabled=true; $('#bzStart').textContent='Clock is running';
  const hint = $('#bzHint'); if (hint) hint.textContent = 'Answer as many as you can.';
  bzStats();
  bzTick(); bzQuestion();
  bzT=setInterval(bzTick,1000);
}
function bzTick(){
  $('#bzClock').textContent = bzLeft;
  $('#bzBar').style.width = (bzLeft/60*100)+'%';
  $('#bzBar').classList.toggle('low', bzLeft <= 15);
  const st = $('#bzStage');
  if (st){ st.classList.toggle('warn', bzLeft <= 20 && bzLeft > 8);
           st.classList.toggle('crit', bzLeft <= 8); }
  if (bzLeft <= 5 && bzLeft > 0 && bzRunning) Snd.reveal();
  if (bzLeft<=0) return bzEnd();
  bzLeft--;
}
function bzStats(){
  const set = (id, v) => { const n = $(id); if (n) n.textContent = v; };
  set('#bzScore', bzScore); set('#bzAsked', bzCount);
  set('#bzHit', bzRight); set('#bzBestN', bzBest);
}
function bzEnd(){
  clearInterval(bzT); bzRunning=false;
  $('#bzStart').disabled=false; $('#bzStart').textContent='Play again';
  const st = $('#bzStage'); if (st) st.classList.remove('warn','crit');
  const beat = bzScore > bzBest;
  $('#bzArea').innerHTML = '<div class="endcard"><div class="eyebrow">Buzzer</div>' +
    '<h3>' + bzScore + ' points</h3>' +
    '<div class="endrow"><div><b>' + bzCount + '</b><span>answered</span></div>' +
    '<div><b>' + bzRight + '</b><span>right</span></div>' +
    '<div><b>' + (bzCount ? Math.round(bzRight/bzCount*100) : 0) + '%</b><span>hit rate</span></div>' +
    '<div><b>' + Math.max(bzBest, bzScore) + '</b><span>your best</span></div></div>' +
    '<p class="endnote">' + (beat ? 'A new best.' : 'Sixty seconds, ' + bzCount + ' questions.') + '</p></div>';
  const hint = $('#bzHint'); if (hint) hint.textContent = 'Sixty seconds. Every answer is a real 2025-26 number.';
  if (bzScore >= 60) Snd.win();
  bzBest = Math.max(bzBest, bzScore);
  bzStats();
  award(bzScore,'Beat the Buzzer · '+bzCount+' questions');
  quip('bz', bzScore >= 60, $('#bzArea'));
}
/* One option button, dressed like every other player row in the app.
   `safe` is the stat the question turns on, so hlLine hides it and the
   stats tied to it -- the fan gets context, never the answer. */
function bzOpt(p, safe){
  const b = el('button','opt');
  b.innerHTML = '<span class="ol1"><span class="pc '+p.pos+'">'+p.pos+'</span><b>'+p.name+'</b></span>'+
                '<span class="ol2">'+hlLine(p, safe)
                   .replace(/^<span class="pc[^>]*>[^<]*<\/span> /,'')
                   .replace(/<\/em> (?=<em|<span)/g, '</em> <s>&middot;</s> ')+'</span>';
  return b;
}
function bzQuestion(){
  if (!bzRunning) return;
  const r = Math.random();
  let kind = r<.40 ? 'hl' : r<.65 ? 'who' : r<.85 ? 'fo' : 'att';
  // the specialist pools can run thin on a real roster -- fall back, never crash
  if (kind==='fo'  && SK.filter(p=>p.fot>=100).length < 2) kind='hl';
  if (kind==='att' && SK.filter(p=>p.att>=50).length  < 2) kind='hl';
  const area = $('#bzArea'); area.innerHTML='';
  if (kind==='hl'){
    const c=rand(HL_SK); let a,b,g=0;
    do{a=rand(SK);b=rand(SK);g++;}while((a===b||a[c.k]===b[c.k])&&g<80);
    area.appendChild(el('div','bzq','Who had more '+c.l.toLowerCase()+'?'));
    const wrap=el('div','bzopts');
    shuffle([a,b]).forEach(p=>{
      const btn=bzOpt(p, c.k);
      btn.onclick=()=>bzAnswer(p[c.k]>=Math.max(a[c.k],b[c.k]), btn, (a[c.k]>b[c.k]?a:b).name+', '+Math.max(a[c.k],b[c.k]));
      wrap.appendChild(btn);
    });
    area.appendChild(wrap);
  } else if (kind==='who'){
    const t=rand(SK), f=rand(HL_SK);
    area.appendChild(el('div','bzq','Which Leaf had <b>'+t[f.k]+'</b> '+f.l.toLowerCase()+'?'));
    const wrong=shuffle(SK.filter(p=>p!==t&&p[f.k]!==t[f.k])).slice(0,2);
    const wrap=el('div','bzopts');
    shuffle([t,...wrong]).forEach(p=>{
      const btn=bzOpt(p, f.k);
      btn.onclick=()=>bzAnswer(p===t, btn, t.name);
      wrap.appendChild(btn);
    });
    area.appendChild(wrap);
  } else if (kind==='fo'){
    const pool = SK.filter(p=>p.fot>=100); let a,b,g=0;
    do{a=rand(pool);b=rand(pool);g++;}while((a===b||a.fow===b.fow)&&g<80);
    area.appendChild(el('div','bzq','Who won more faceoffs?'));
    const wrap=el('div','bzopts');
    shuffle([a,b]).forEach(p=>{
      const btn=bzOpt(p,'fow');
      btn.onclick=()=>bzAnswer(p.fow>=Math.max(a.fow,b.fow), btn, (a.fow>b.fow?a:b).name+', '+Math.max(a.fow,b.fow)+' draws won');
      wrap.appendChild(btn);
    });
    area.appendChild(wrap);
  } else {
    const pool = SK.filter(p=>p.att>=50); let a,b,g=0;
    do{a=rand(pool);b=rand(pool);g++;}while((a===b||a.att===b.att)&&g<80);
    area.appendChild(el('div','bzq','Who fired more shot attempts?'));
    const wrap=el('div','bzopts');
    shuffle([a,b]).forEach(p=>{
      const btn=el('button','opt',p.name);
      btn.onclick=()=>bzAnswer(p.att>=Math.max(a.att,b.att), btn, (a.att>b.att?a:b).name+', '+Math.max(a.att,b.att)+' attempts');
      wrap.appendChild(btn);
    });
    area.appendChild(wrap);
  }
}
function bzAnswer(ok, btn, truth){
  if (!bzRunning) return;
  bzCount++;
  if (ok){ bzScore+=15; bzRight++; btn.classList.add('right'); floater('+15', true); Snd.ding(); }
  else { bzScore=Math.max(0,bzScore-5); btn.classList.add('wrong'); floater('-5', false); Snd.thud(); }
  bzStats();
  document.querySelectorAll('#bzArea .opt').forEach(b=>b.disabled=true);
  setTimeout(bzQuestion, ok?260:620);
}

/* ══ LEADERBOARDS ════════════════════════════════════════════════ */
const LB_CP = [
  {who:'@leafsforever91',  tot:5140, note:'9 games played'},
  {who:'@dundasandbloor',  tot:4155, note:'7 games played'},
  {who:'@bunting_stan',    tot:3930, note:'9 games played'},
  {who:'@sheldons_whistle',tot:2990, note:'6 games played'},
  {who:'@holland_era',     tot:2415, note:'5 games played'},
  {who:'@basement_gm',     tot:1870, note:'4 games played'},
  {who:'@puckluck416',     tot:1240, note:'3 games played'},
];
/* Seeded from real legal builds, scored by the same functions the game uses --
   no invented totals. LB_ULT tot = projected fantasy points of the six-part
   build; LB_STORMY tot = categories won out of six.                         */
const LB_ULT = [
  {who:'@leafsforever91',   build:'Tavares / Nylander / Matthews / Joshua / Tanev / Domi',     tot:6.64},
  {who:'@dundasandbloor',   build:'Matthews / Nylander / Tavares / Joshua / Tanev / MacEwen',  tot:6.51},
  {who:'@bunting_stan',     build:'Matthews / Nylander / Raddysh / Joshua / McCabe / Domi',    tot:6.21},
  {who:'@sheldons_whistle', build:'Matthews / Tavares / Nylander / Knies / Tanev / Duhaime',   tot:5.91},
  {who:'@holland_era',      build:'Matthews / Knies / Nylander / Duhaime / McCabe / Domi',     tot:5.88},
  {who:'@basement_gm',      build:'Tavares / Raddysh / Matthews / Groulx / Rielly / McCabe',   tot:5.52},
  {who:'@puckluck416',      build:'Nylander / Tavares / Matthews / Lorentz / Myers / Sissons', tot:5.06},
];
const LB_STORMY = [
  {who:'@leafsforever91',   build:'Matthews / Knies / Joshua / Raddysh / Rielly',          res:'6-0', tot:6},
  {who:'@dundasandbloor',   build:'Tavares / Knies / Joshua / Rielly / Tanev',             res:'5-1', tot:5},
  {who:'@bunting_stan',     build:'Matthews / Joshua / Sissons / Rielly / Andrae',         res:'4-2', tot:4},
  {who:'@sheldons_whistle', build:'Matthews / Domi / Blueger / Tanev / Raddysh',           res:'4-2', tot:4},
  {who:'@holland_era',      build:'Matthews / Tavares / Knies / Raddysh / Ekman-Larsson',  res:'3-3', tot:3},
  {who:'@basement_gm',      build:'Matthews / Tavares / Knies / Raddysh / Rielly',         res:'3-3', tot:3},
  {who:'@puckluck416',      build:'Roslovic / Groulx / MacEwen / Andrae / Stecher',        res:'1-5', tot:1},
];
let lbView='cp';
function drawLB(){
  /* the room is a different table -- live fans, not a seeded field -- so it
     swaps the whole card rather than pretending to be another column set */
  const roomOn = lbView === 'room';
  const tbl = $('#lbBody').closest('.card'), rb = $('#roomBoard');
  if (tbl) tbl.style.display = roomOn ? 'none' : '';
  if (rb)  rb.style.display  = roomOn ? '' : 'none';
  ['cp','ult','stormy','room'].forEach(v => { const b=$('#lbTab_'+v); if (b) b.className = lbView===v?'act':'ghost'; });
  if (roomOn){
    ROOM.drawRoomBoard();
    $('#lbCap').textContent = ROOM.ok
      ? 'Every window on this machine is a fan. Scores post as they are earned. No server involved.'
      : 'The room needs browser storage, which a file opened straight from disk does not get. Served over http (or in production) this board is live.';
    return;
  }
  const src = lbView==='cp' ? [...LB_CP, {who:'You', tot:CP, note:CP_LOG.length+' scoring plays', you:true}]
            : lbView==='ult' ? LB_ULT : LB_STORMY;
  const rows=[...src].sort((a,b)=>b.tot-a.tot);
  const max = lbView==='stormy' ? 6 : (rows.length?rows[0].tot:1);
  const col2 = lbView==='cp' ? (r=>r.note||'') : (r=>r.build||'');
  const fmt  = lbView==='cp'  ? (r=>Math.round(r.tot).toLocaleString())
             : lbView==='ult' ? (r=>r.tot.toFixed(2))
             : (r=>r.res||(r.tot+'-'+(6-r.tot)));
  const MEDAL = [ART.badge_1, ART.badge_2, ART.badge_3];
  const CRESTRK = ['#FFFFFF','#C7DAF3','#8FB3E0'];
  $('#lbBody').innerHTML = rows.map((r,i)=>
    '<tr class="'+(r.you?'you':'')+'"><td class="rank">'+
      (CRESTRK[i] ? leafSVG(18, CRESTRK[i]) : (i+1))+'</td>'+
    '<td><b>'+r.who+'</b></td><td class="bld">'+col2(r)+'</td>'+
    '<td class="barcell"><div class="bar"><i style="width:'+(max?r.tot/max*100:0)+'%"></i></div></td>'+
    '<td class="tot">'+fmt(r)+'</td></tr>').join('');
  $('#lbHead2').textContent = lbView==='cp'?'Activity':'Lineup';
  $('#lbHead4').textContent = lbView==='cp'?'Citrus points':lbView==='ult'?'Projected pts':'Categories';
  $('#lbCap').textContent = lbView==='cp'
    ? 'One score across all ten games. This is the number a fan comes back to move.'
    : lbView==='ult'
      ? 'Six slots, six different Leafs, season rates per game. Perfect is '+PERFECT.total.toFixed(2)+
        '. The best legal assignment, not the sum of the category leaders ('+GREEDY.toFixed(2)+
        ', which no build can reach). The best single Leaf tonight is '+last(BEST_ONE.name)+' at '+sixCat(BEST_ONE).toFixed(2)+'.'
      : 'Three forwards and a pair against Stormy’s five, six categories, 3-3 is a draw. Across all 3,300 legal lineups: 33.2% win, 18.7% draw, 48.1% loss. A 6-0 sweep exists in 28 of them.';
}

