/* ══ GAME 10: CALL IT ════════════════════════════════════════════
   The one game only Citrus can build, and the one that gives a fan a
   reason to keep the app open for a whole game rather than a minute.

   The league's own second screen (GameFlow) VISUALISES shot pressure. It shows you where the attempts came from. Nobody lets you play
   against the model. That is the gap.

   Every question is a real shot: real coordinates out of 1,026,149
   play-by-play rows, taken by a named Leaf, with the real expected-goals
   value the Citrus model gave it. You call the danger before the number
   is revealed and you are scored on how close your read was -- NOT on
   whether it went in. That distinction is the whole design:

     * outcome prediction is mostly variance, and reads as a betting
       product to a club's compliance desk;
     * chance-quality reading is a learnable skill, objectively gradeable
       in a tenth of a second, and after fifty calls a fan genuinely
       starts seeing the slot the way the model does.

   It also works cold. Live, it fires on every shot -- roughly thirty a
   game, five seconds each. Out of season it runs on the same historical
   shot database, so the game is never empty.                        */
/* ── the offensive zone, to NHL spec ──────────────────────────────
   Drawn in feet. The viewBox is 75 x 85. The true proportions of the
   zone, so a faceoff circle is a circle. The previous version stretched
   a square viewBox into a portrait box with preserveAspectRatio="none",
   which distorted every arc on the sheet.

   Every measurement below is the NHL rule, not an approximation:
     end boards 11 ft behind the goal line, 28 ft corner radius
     crease  4.5 ft straights 1 ft outside each post, 6 ft radius arc
     net     6 ft wide, 40 in deep
     trapezoid 22 ft on the goal line flaring to 28 ft at the boards
     faceoff circles 15 ft radius, 20 ft out, 22 ft off centre
     hash marks 3 ft long, 5 ft 7 in apart                            */
const RK = {x0:25, x1:100, gl:89, y0:-42.5, y1:42.5};
const vx = f => f - RK.x0, vy = f => f + 42.5;

function rinkSVG(){
  const GL = vx(RK.gl), EB = vx(100), CR = 28;
  const arc = (r,x,y,sw) => 'A'+r+' '+r+' 0 0 '+sw+' '+x+' '+y;
  const SHEET = 'M0 0 H'+(EB-CR)+' '+arc(CR, EB, CR, 1)+
    ' V'+(85-CR)+' '+arc(CR, EB-CR, 85, 1)+' H0 Z';
  return '<svg viewBox="-1 -1 77 87" class="rinkbg" aria-hidden="true">'+
    '<defs><clipPath id="sheetclip"><path d="'+SHEET+'"/></clipPath></defs>'+
    /* the sheet, with the 28 ft corners cut in, and the boards around it */
    '<path fill="#EEF3FA" stroke="#8FA6C4" stroke-width=".5" d="'+SHEET+'"/>'+
    '<g clip-path="url(#sheetclip)">'+
    /* blue line, 12 in */
    '<rect x="0" y="0" width="1" height="85" fill="#2D6BD6"/>'+
    /* trapezoid: 22 ft on the goal line, 28 ft at the boards */
    '<path fill="none" stroke="#C8202E" stroke-width=".28" opacity=".85" d="'+
      'M'+GL+' '+vy(-11)+' L'+EB+' '+vy(-14)+' M'+GL+' '+vy(11)+' L'+EB+' '+vy(14)+'"/>'+
    /* goal line, 2 in */
    '<rect x="'+(GL-.08)+'" y="0" width=".17" height="85" fill="#C8202E"/>'+
    /* crease: 4.5 ft straights a foot outside each post, 6 ft arc */
    '<path fill="#BFD6F2" fill-opacity=".9" stroke="#2D6BD6" stroke-width=".28" d="'+
      'M'+GL+' '+vy(-4)+' H'+(GL-4.5)+' '+arc(6, GL-4.5, vy(4), 0)+' H'+GL+'"/>'+
    /* crease hash marks, 4 ft off the goal line */
    '<path stroke="#C8202E" stroke-width=".22" d="M'+(GL-4)+' '+vy(-4)+' v.42 '+
      'M'+(GL-4)+' '+vy(4)+' v-.42"/>'+
    /* net: 6 ft mouth, 40 in deep */
    '<path fill="#F6FAFF" stroke="#C8202E" stroke-width=".34" d="'+
      'M'+GL+' '+vy(-3)+' h3.33 v6 h-3.33"/>'+
    /* faceoff circles, spots and hash marks */
    [-22, 22].map(o => {
      const cx = vx(69), cy = vy(o);
      return '<circle cx="'+cx+'" cy="'+cy+'" r="15" fill="none" stroke="#C8202E" stroke-width=".28"/>'+
        '<circle cx="'+cx+'" cy="'+cy+'" r="1" fill="#C8202E"/>'+
        [-1,1].map(sy => [-1,1].map(sx =>
          '<path stroke="#C8202E" stroke-width=".26" d="M'+(cx+sx*2.79)+' '+
          (cy+sy*15)+' v'+(sy*3)+'"/>').join('')).join('');
    }).join('')+
    '</g>'+
  '</svg>';
}

function drawRink(x,y,show){
  const px = f => (vx(f)/75)*100, py = f => (vy(f)/85)*100;
  $('#clRink').innerHTML = rinkSVG()+
    '<span class="shotline" style="left:'+px(x)+'%;top:'+py(y)+'%;width:'+
      Math.hypot(px(RK.gl)-px(x), py(0)-py(y))+'%;transform:rotate('+
      (Math.atan2(py(0)-py(y), px(RK.gl)-px(x))*180/Math.PI)+'deg)"></span>'+
    '<span class="shotdot'+(show?' show':'')+'" style="left:'+px(x)+'%;top:'+py(y)+'%"></span>';
}

/* ── Call It: where does he score from ──────────────────────────
   Not an outcome caller. This is the map game: pick three Leafs, drop
   a pin on the ice where you think each of them scores tonight, and
   the puck decides how close you were.

   Every goal in this game has real coordinates out of nhl_shots, so
   the distance between your pin and the spot he actually scored from
   is a real measurement in feet, not a score we invented. Toronto put
   six past Anaheim and every one came off a different stick, which is
   what makes picking three a genuine call rather than a formality.

   Scoring says out loud what it rewards:
       25 points for picking a man who scores at all
       up to 100 more for how close the pin was, linear to 45 ft
   Pick a man who does not score and the pin is worth nothing, which
   is the whole tension: the safe three are not the accurate three.  */
const GEO_MAX = 3;
const GEO_FADE = 45;                       // feet at which the bonus runs out
const geoPts = d => 25 + Math.max(0, Math.round(100 * (1 - d / GEO_FADE)));

/* the viewBox is "-1 -1 77 87", so a percentage inside the box is not a
   percentage of the 75x85 sheet. Map both ways off the same constants or
   a pin lands a foot from where the fan put it. */
const VB = {x:-1, y:-1, w:77, h:87};
const pctX = f => ((vx(f) - VB.x) / VB.w) * 100;
const pctY = f => ((vy(f) - VB.y) / VB.h) * 100;
const feetX = p => (p / 100) * VB.w + VB.x + RK.x0;
const feetY = p => (p / 100) * VB.h + VB.y - 42.5;

const GEO_GOALS = EV.filter(e => e.kind === 'G' && e.home);
const GEO_POOL  = BOX_L.filter(r => SEASON[r.name]);

let geoPicks = [], geoPins = {}, geoActive = null, geoLocked = false, geoDone = {};

function geoGoalFor(name){
  const short = name.split(' ')[0][0] + '. ' + name.split(' ').slice(1).join(' ');
  const mine = GEO_GOALS.filter(e => e.sh === short);
  if (!mine.length) return null;
  const pin = geoPins[name];
  if (!pin) return mine[0];
  return mine.reduce((best, e) =>
    Math.hypot(e.x - pin.x, e.y - pin.y) < Math.hypot(best.x - pin.x, best.y - pin.y) ? e : best, mine[0]);
}

/* ── the sheet, tappable ─────────────────────────────────────────── */
function geoRink(){
  const box = $('#clRink'); if (!box) return;
  let html = rinkSVG();
  geoPicks.forEach((n, i) => {
    const pin = geoPins[n]; if (!pin) return;
    const res = geoDone[n];
    html += '<span class="geopin p' + i + (geoActive === n ? ' on' : '') + (res ? ' settled' : '') +
            '" style="left:' + pctX(pin.x) + '%;top:' + pctY(pin.y) + '%">' + (i+1) + '</span>';
    if (res && res.goal){
      const gx = pctX(res.goal.x), gy = pctY(res.goal.y), px = pctX(pin.x), py = pctY(pin.y);
      html += '<span class="geoline" style="left:' + px + '%;top:' + py + '%;width:' +
              Math.hypot(gx - px, gy - py) + '%;transform:rotate(' +
              (Math.atan2(gy - py, gx - px) * 180 / Math.PI) + 'deg)"></span>' +
              '<span class="geogoal p' + i + '" style="left:' + gx + '%;top:' + gy + '%"></span>';
    }
  });
  box.innerHTML = html;
  box.onclick = e => {
    if (geoLocked || !geoActive) return;
    const r = box.getBoundingClientRect();
    const x = feetX((e.clientX - r.left) / r.width * 100);
    const y = feetY((e.clientY - r.top) / r.height * 100);
    if (x < RK.x0 || x > 99 || y < -42 || y > 42) return;
    geoPins[geoActive] = { x: +x.toFixed(1), y: +y.toFixed(1) };
    const nxt = geoPicks.find(n => !geoPins[n]);
    geoActive = nxt || geoActive;
    Snd.pick && Snd.pick(); geoDraw();
  };
}

/* ── the three you picked, and the pin state of each ─────────────── */
function geoSlots(){
  const box = $('#clSlots'); if (!box) return;
  box.innerHTML = geoPicks.length ? geoPicks.map((n, i) => {
    const pin = geoPins[n], res = geoDone[n];
    const p = GEO_POOL.find(x => x.name === n) || {num:'', pos:''};
    return '<button class="geoslot p' + i + (geoActive === n ? ' on' : '') + '" data-n="' + n + '">' +
      '<span class="geonum">' + (i+1) + '</span>' +
      faceOf(n, p.num, 28) +
      '<span class="geoname">' + n + '</span>' +
      '<span class="geostate">' + (res
          ? (res.goal ? '<b class="hit">' + res.dist.toFixed(0) + ' ft out</b> +' + res.pts
                      : '<b class="cold">no goal</b>')
          : pin ? Math.round(89 - pin.x) + ' ft from the net'
                : 'tap the ice') + '</span></button>';
  }).join('') : '<div class="geoempty">Pick three Leafs below, then drop a pin for each.</div>';
  box.querySelectorAll('.geoslot').forEach(b => b.onclick = () => {
    if (geoLocked) return; geoActive = b.dataset.n; geoDraw();
  });
}

/* ── the roster you pick three from ──────────────────────────────── */
function geoPool(){
  const box = $('#clPool'); if (!box) return;
  box.innerHTML = '';
  [...GEO_POOL].sort((a,b) => perGame(b.name,'g') - perGame(a.name,'g')).forEach(p => {
    const on = geoPicks.includes(p.name);
    const full = geoPicks.length >= GEO_MAX && !on;
    const r = prow(p, {
      on: on,
      line: '<em>' + perGame(p.name,'g').toFixed(2) + '</em> goals a game this season <s>&middot;</s>' +
            '<em>' + perGame(p.name,'sog').toFixed(2) + '</em> shots',
      val: null
    });
    if (full || geoLocked){ r.disabled = true; r.classList.add('gone'); }
    r.onclick = () => {
      if (geoLocked) return;
      if (on){ geoPicks = geoPicks.filter(n => n !== p.name); delete geoPins[p.name];
               if (geoActive === p.name) geoActive = geoPicks[0] || null; }
      else if (geoPicks.length < GEO_MAX){
        geoPicks.push(p.name); geoActive = p.name; Snd.pick && Snd.pick();
        const rink = $('#clRink');
        if (rink && window.matchMedia('(max-width:860px)').matches)
          rink.scrollIntoView({ block:'center', behavior: CALM ? 'auto' : 'smooth' });
      }
      geoDraw();
    };
    box.appendChild(r);
  });
}

function geoDraw(){
  geoRink(); geoSlots(); geoPool();
  const ready = geoPicks.length === GEO_MAX && geoPicks.every(n => geoPins[n]);
  const go = $('#clGo');
  if (go){ go.disabled = !ready || geoLocked;
           go.textContent = geoLocked ? (CLOCK.over ? 'Settled' : 'Locked, watching') : 'Lock your three'; }
  const hint = $('#clHint');
  if (hint) hint.textContent = geoLocked
    ? (CLOCK.over ? 'Settled.' : 'Watching for your three.')
    : geoPicks.length < GEO_MAX ? (GEO_MAX - geoPicks.length) + ' more to pick'
    : !ready ? 'now drop a pin for each' : 'ready';
  const cnt = $('#clCount'); if (cnt) cnt.textContent = geoPicks.length + ' of 3';
  const pts = $('#clPts');
  if (pts) pts.textContent = Object.values(geoDone).reduce((s,r) => s + r.pts, 0);
  const bestEl = $('#clBest');
  if (bestEl){
    const hits = Object.values(geoDone).filter(r => r.goal);
    bestEl.textContent = hits.length ? Math.min(...hits.map(r => r.dist)).toFixed(0) + ' ft' : '-';
  }
  if (CLOCK.over && geoLocked) geoFinal();
}

function geoLock(){
  if (geoLocked || geoPicks.length !== GEO_MAX || !geoPicks.every(n => geoPins[n])) return;
  geoLocked = true; Snd.ding && Snd.ding(); geoDraw();
  if (!CLOCK.running && !CLOCK.over) CLOCK.start();
}

/* a goal by one of your three settles that pin the moment it goes in */
function geoSettle(e){
  const who = SHORT2FULL[e.sh] || e.sh;
  if (!geoLocked || !geoPicks.includes(who) || geoDone[who]) return;
  const pin = geoPins[who];
  const dist = Math.hypot(e.x - pin.x, e.y - pin.y);
  geoDone[who] = { goal: e, dist, pts: geoPts(dist) };
  award(geoPts(dist), 'Call It · ' + who + ' from ' + dist.toFixed(0) + ' ft');
  if (dist <= 12){ confetti(); Snd.win && Snd.win(); } else Snd.ding && Snd.ding();
  const msg = $('#clMsg');
  if (msg) msg.innerHTML = '<span class="up">' + who + ' scored. Your pin was <b>' +
    dist.toFixed(0) + ' ft</b> away. +' + geoPts(dist) + '</span>';
  geoDraw();
}

function geoFinal(){
  if ($('#clFinal')) return;
  geoPicks.forEach(n => { if (!geoDone[n]) geoDone[n] = { goal:null, dist:null, pts:0 }; });
  const hits = geoPicks.filter(n => geoDone[n].goal);
  const total = geoPicks.reduce((s,n) => s + geoDone[n].pts, 0);
  const best = hits.length ? Math.min(...hits.map(n => geoDone[n].dist)) : null;
  const card = el('div','endcard'); card.id = 'clFinal';
  card.innerHTML = '<div class="eyebrow">Full time</div><h3>Toronto 6, Anaheim 4</h3>' +
    '<div class="endrow"><div><b>' + hits.length + '</b><span>of 3 scored</span></div>' +
    '<div><b>' + (best === null ? '-' : best.toFixed(0) + ' ft') + '</b><span>closest pin</span></div>' +
    '<div><b>' + total + '</b><span>points</span></div></div>' +
    '<p class="endnote">' + (hits.length
      ? 'Toronto scored six, off six different sticks. ' +
        geoPicks.map(n => n.split(' ').pop() + ' ' + (geoDone[n].goal ? geoDone[n].dist.toFixed(0) + ' ft' : 'no goal')).join(', ') + '.'
      : 'None of your three scored. Six Leafs did.') + '</p>' +
    '<button class="act" id="clAgain">Pick three again</button>';
  $('#clReveal').innerHTML = ''; $('#clReveal').appendChild(card);
  $('#clAgain').onclick = () => {
    geoPicks = []; geoPins = {}; geoDone = {}; geoActive = null; geoLocked = false;
    $('#clReveal').innerHTML = ''; $('#clMsg').innerHTML = ''; CLOCK.reset(); geoDraw();
  };
}

CLOCK.on((kind, e) => {
  if (kind === 'reset'){ const f = $('#clFinal'); if (f) f.remove(); geoDone = {}; geoDraw(); return; }
  if (kind === 'ev' && e.kind === 'G' && e.home) geoSettle(e);
  if (kind === 'final') geoDraw();
});
const clIdle = geoDraw;   // the boot line and the score bug both call this

/* ══ PLAYER DASHBOARD ═════════════════════════════════════════════
   The page a club app should have. Everything here is measured, and
   the things we cannot measure are listed at the bottom of the panel
   rather than quietly filled in.

   Chart colours are not hand-picked. GOAL_C / XG_C were run through a
   palette validator against this surface (#141618) and pass the
   lightness band, chroma floor, CVD separation (ΔE 22.9 protan, worst
   adjacent) and the 3:1 mark-contrast check. The brand accent #FF6B1A
   sits just outside the dark-mode lightness band, so chart marks use a
   slightly darker orange while the UI keeps the accent.            */
const GOAL_C = '#E86A20', XG_C = '#3A93CF';
// A percentile bar and a nightly-points bar are magnitude, not identity. Paint
// them in the club's own ice blue so nothing but a goal wears the goal colour.
const METER_C = '#8FBEF0';
const GRID   = 'rgba(255,255,255,.09)';
const CAREER_COLS = ['season','sog','goals','xg','fin','dist','rush','reb'];

let dashPid = PD.roster[0].id, dashTable = false;
const P_BY = {}; PD.roster.forEach(p => P_BY[p.id] = p);
const posGrp = p => p.pos === 'D' ? 'D' : 'F';
const age = dob => { const b = new Date(dob + 'T00:00:00'), n = new Date('2026-09-29T00:00:00');
  let a = n.getFullYear() - b.getFullYear();
  if (n.getMonth() < b.getMonth() || (n.getMonth() === b.getMonth() && n.getDate() < b.getDate())) a--;
  return a; };
const ft = inches => Math.floor(inches / 12) + "'" + (inches % 12) + '"';

/* one tooltip, moved around -- an HTML chart that cannot be interrogated
   is a picture, and a picture is what their app already has */
let TIP;
function tipShow(e, html){
  if (!TIP){ TIP = el('div','charttip'); document.body.appendChild(TIP); }
  TIP.innerHTML = html; TIP.style.display = 'block';
  const r = TIP.getBoundingClientRect();
  TIP.style.left = Math.min(window.innerWidth - r.width - 8, Math.max(8, e.clientX - r.width / 2)) + 'px';
  TIP.style.top  = Math.max(8, e.clientY - r.height - 14) + 'px';
}
const tipHide = () => { if (TIP) TIP.style.display = 'none'; };
const svgEl = (t, a) => { const n = document.createElementNS('http://www.w3.org/2000/svg', t);
  for (const k in a) n.setAttribute(k, a[k]); return n; };

/* ── chart 1: goals against expected, by season ──────────────────── */
function chartGoals(host, rows, name){
  host.innerHTML = '';
  if (!rows.length) { host.innerHTML = '<div class="empty">No shot-quality history for this player.</div>'; return; }
  const W = 760, H = 250, L = 38, R = 12, T = 26, B = 30;
  const iw = W - L - R, ih = H - T - B;
  const max = Math.max(...rows.map(r => Math.max(r[2], r[3]))) * 1.16 || 1;
  const bw = iw / rows.length, pad = bw * 0.22, half = (bw - pad * 2 - 2) / 2;
  const y = v => T + ih - (v / max) * ih;
  const s = svgEl('svg', {viewBox:`0 0 ${W} ${H}`, class:'chart', role:'img',
    'aria-label': `${name}: goals against expected goals, ${rows[0][0]} to ${rows[rows.length-1][0]}. ` +
      rows.map(r => `${r[0]}: ${r[2]} goals, ${r[3].toFixed(1)} expected`).join('. ')});
  // gridlines
  for (let i = 0; i <= 4; i++){
    const v = max * i / 4;
    s.appendChild(svgEl('line', {x1:L, x2:W-R, y1:y(v), y2:y(v), stroke:GRID}));
    const t = svgEl('text', {x:L-7, y:y(v)+4, class:'ax', 'text-anchor':'end'});
    t.textContent = Math.round(v); s.appendChild(t);
  }
  rows.forEach((r, i) => {
    const x0 = L + i * bw + pad;
    [[r[2], GOAL_C, 'Goals'], [r[3], XG_C, 'Expected']].forEach(([v, c, lab], k) => {
      const x = x0 + k * (half + 2), h = Math.max(1, T + ih - y(v));
      const b = svgEl('rect', {x, y:y(v), width:half, height:h, rx:Math.min(4, half/2), fill:c, class:'mk'});
      b.addEventListener('mousemove', e => tipShow(e,
        `<b>${r[0]}-${String(r[0]+1).slice(2)}</b><br>${r[2]} goals · ${r[3].toFixed(1)} expected<br>` +
        `<span style="color:${r[4]>=0?GOAL_C:XG_C}">${r[4]>=0?'+':''}${r[4].toFixed(1)} vs expected</span><br>` +
        `${r[1]} shots on goal · ${r[5].toFixed(0)} ft average`));
      b.addEventListener('mouseleave', tipHide);
      s.appendChild(b);
    });
    // direct label on goals only -- a number on every mark is noise
    const g = svgEl('text', {x:x0 + half/2, y:y(r[2]) - 6, class:'vl', 'text-anchor':'middle'});
    g.textContent = r[2]; s.appendChild(g);
    const xl = svgEl('text', {x:L + i*bw + bw/2, y:H-10, class:'ax', 'text-anchor':'middle'});
    xl.textContent = String(r[0]).slice(2) + '-' + String(r[0]+1).slice(2); s.appendChild(xl);
  });
  host.appendChild(s);
  host.appendChild(el('div','legend',
    `<span><i style="background:${GOAL_C}"></i>Goals scored</span>` +
    `<span><i style="background:${XG_C}"></i>Expected goals. Citrus xG model</span>`));
}

/* ── the finishing strip: same x scale, polarity by position ─────── */
function chartFin(host, rows){
  host.innerHTML = '';
  if (!rows.length) return;
  const W = 760, H = 84, L = 38, R = 12, T = 14, B = 16;
  const iw = W - L - R, ih = H - T - B, mid = T + ih/2;
  const m = Math.max(...rows.map(r => Math.abs(r[4]))) * 1.15 || 1;
  const bw = iw / rows.length, bar = bw * 0.5;
  const s = svgEl('svg', {viewBox:`0 0 ${W} ${H}`, class:'chart', role:'img',
    'aria-label':'Goals above or below expected, per season: ' +
      rows.map(r => `${r[0]} ${r[4]>=0?'plus':'minus'} ${Math.abs(r[4]).toFixed(1)}`).join(', ')});
  s.appendChild(svgEl('line', {x1:L, x2:W-R, y1:mid, y2:mid, stroke:'rgba(255,255,255,.28)'}));
  rows.forEach((r, i) => {
    const v = r[4], h = Math.max(2, Math.abs(v) / m * (ih/2));
    const x = L + i*bw + (bw-bar)/2;
    const b = svgEl('rect', {x, y: v>=0 ? mid-h : mid, width:bar, height:h, rx:3,
                             fill: v>=0 ? GOAL_C : XG_C, class:'mk'});
    b.addEventListener('mousemove', e => tipShow(e,
      `<b>${r[0]}-${String(r[0]+1).slice(2)}</b><br>${v>=0?'Scored ':'Missed '}${Math.abs(v).toFixed(1)} ` +
      `${v>=0?'more than':'fewer than'} the chances were worth`));
    b.addEventListener('mouseleave', tipHide);
    s.appendChild(b);
    const t = svgEl('text', {x:L+i*bw+bw/2, y: v>=0 ? mid-h-5 : mid+h+13, class:'vl', 'text-anchor':'middle'});
    t.textContent = (v>=0?'+':'') + v.toFixed(1); s.appendChild(t);
  });
  host.appendChild(s);
}

/* ── chart 2: where he ranks, inside his own position ────────────── */
const RANKS = [['fp','Fantasy points'],['p','Points'],['g','Goals'],['sog','Shots on goal'],
               ['att','Shot attempts'],['hit','Hits'],['blk','Blocks'],['tk','Takeaways'],['toi','Ice time']];
function chartRank(host, p){
  host.innerHTML = '';
  RANKS.forEach(([k, lab]) => {
    const q = p.q[k]; if (q == null) return;
    const row = el('div','qrow');
    row.innerHTML = `<span class="ql">${lab}</span>` +
      `<span class="qbar"><i style="width:${q}%;background:${METER_C}"></i><b class="q50"></b></span>` +
      `<span class="qv">${q}<sup>${q%10===1&&q%100!==11?'st':q%10===2&&q%100!==12?'nd':q%10===3&&q%100!==13?'rd':'th'}</sup></span>`;
    row.addEventListener('mousemove', e => tipShow(e,
      `<b>${lab}</b><br>${q}th percentile among ${p.npos} ${posGrp(p)==='D'?'defencemen':'forwards'}<br>` +
      `<span style="opacity:.7">per game, minimum 20 games played</span>`));
    row.addEventListener('mouseleave', tipHide);
    host.appendChild(row);
  });
}

/* ── chart 3: last twenty games ──────────────────────────────────── */
function chartForm(host, pid, p){
  const f = PD.form[String(pid)];
  host.innerHTML = '';
  if (!f){ host.innerHTML = '<div class="empty">Game-by-game log is loaded for the ten players in the demo set. The other nine read from the same table.</div>'; return; }
  const W = 620, H = 170, L = 30, R = 8, T = 18, B = 26;
  const iw = W-L-R, ih = H-T-B;
  const vals = f.map(d => d[1]);
  const max = Math.max(...vals) * 1.12 || 1;
  const med = [...vals].sort((a,b)=>a-b)[Math.floor(vals.length/2)];
  const bw = iw / f.length, bar = bw * 0.62;
  const y = v => T + ih - (v/max)*ih;
  const s = svgEl('svg', {viewBox:`0 0 ${W} ${H}`, class:'chart', role:'img',
    'aria-label':`Fantasy points in ${p.n}'s last ${f.length} games, median ${med.toFixed(1)}`});
  for (let i=0;i<=3;i++){ const v = max*i/3;
    s.appendChild(svgEl('line',{x1:L,x2:W-R,y1:y(v),y2:y(v),stroke:GRID}));
    const t = svgEl('text',{x:L-6,y:y(v)+4,class:'ax','text-anchor':'end'}); t.textContent = v.toFixed(0); s.appendChild(t); }
  f.forEach((d,i) => {
    const h = Math.max(1.5, T+ih-y(d[1]));
    const b = svgEl('rect',{x:L+i*bw+(bw-bar)/2, y:y(d[1]), width:bar, height:h, rx:2, fill:METER_C, class:'mk'});
    b.addEventListener('mousemove', e => tipShow(e,
      `<b>${d[0]}</b><br>${d[1].toFixed(1)} fantasy points<br>${d[2]} G · ${d[3]} A`));
    b.addEventListener('mouseleave', tipHide);
    s.appendChild(b);
  });
  const ml = svgEl('line',{x1:L,x2:W-R,y1:y(med),y2:y(med),stroke:'#fff','stroke-dasharray':'4 4','stroke-opacity':'.55'});
  s.appendChild(ml);
  const mt = svgEl('text',{x:L, y:T-6, class:'vl','text-anchor':'start'});
  mt.textContent = 'median ' + med.toFixed(1); s.appendChild(mt);
  host.appendChild(s);
  const best = f.reduce((m,d) => d[1] > m[1] ? d : m, f[0]);
  const above = f.filter(d => d[1] >= med).length;
  const gs = f.reduce((s,d)=>s+d[2],0), as = f.reduce((s,d)=>s+d[3],0);
  const blanks = f.filter(d => d[2]+d[3] === 0).length;
  host.appendChild(el('div','formstats',
    `<div><b>${best[1].toFixed(1)}</b><span>Best night &middot; ${best[0]}</span></div>` +
    `<div><b>${above}/${f.length}</b><span>At or above his median</span></div>` +
    `<div><b>${gs}G ${as}A</b><span>Over the span</span></div>` +
    `<div><b>${blanks}</b><span>Held pointless</span></div>`));
}

/* ── the numbers behind the charts, for anyone who wants them ───── */
function dashNumbers(rows, p){
  if (!rows.length) return '';
  return '<table class="numtbl"><thead><tr><th>Season</th><th>SOG</th><th>Goals</th><th>xG</th>' +
    '<th>vs expected</th><th>Avg shot</th><th>Rush</th><th>Rebound</th></tr></thead><tbody>' +
    rows.map(r => `<tr><td>${r[0]}-${String(r[0]+1).slice(2)}</td><td class="tot">${r[1]}</td>` +
      `<td class="tot">${r[2]}</td><td class="tot">${r[3].toFixed(2)}</td>` +
      `<td class="tot" style="color:${r[4]>=0?GOAL_C:XG_C}">${r[4]>=0?'+':''}${r[4].toFixed(2)}</td>` +
      `<td class="tot">${r[5].toFixed(1)} ft</td><td class="tot">${r[6]}</td><td class="tot">${r[7]}</td></tr>`).join('') +
    '</tbody></table>';
}

/* ══ SHOT MAP ═════════════════════════════════════════════════════
   Offensive-zone shot chart from nhl_shots, 1,026,149 shots across
   nine seasons, every one with coordinates. This build draws the
   2025-26 offensive zone: a 5-foot density grid for all shots, with
   goals plotted individually on top and sized by the chance quality
   our model assigned them.

   Rink geometry is NHL standard: centre ice x=0, blue lines at ±25,
   goal lines at ±89, boards at ±100, half-width 42.5. So the grid,
   which starts at x=25, IS exactly the offensive zone.

   Orientation is the one every shot chart uses. The shooter is
   looking up the page at the net.                                */
const SM_W = 85, SM_H = 75;                        // feet
const smx = y => y + 42.5;                          // rink y -> svg x
const smy = x => 100 - x;                           // rink x -> svg y

function chartShots(host, pid, p, career2025){
  host.innerHTML = '';
  const grid  = SD.grid[String(pid)];
  const goals = SD.goals[String(pid)] || [];
  if (!grid){
    host.innerHTML = '<div class="empty">Shot coordinates are loaded for the ten players in the demo set. ' +
      'The table behind it holds 1,026,149 shots across nine seasons. Every skater, every game.</div>';
    return;
  }
  const max = Math.max(...grid.map(c => c[2]));
  const drawn = grid.reduce((s,c) => s + c[2], 0);
  const off   = SD.offGrid[String(pid)] || 0;
  const goalsOff = career2025 ? career2025[2] - goals.length : 0;

  const s = svgEl('svg', {viewBox:`0 0 ${SM_W} ${SM_H}`, class:'rink', role:'img',
    'aria-label': `${p.n} offensive-zone shot map, 2025-26. ${drawn} shots drawn, ` +
      `${goals.length} goals. Densest area ${max} shots in one five-foot square.`});

  // ── the rink, drawn plainly. no decoration. ──
  s.appendChild(svgEl('rect', {x:0, y:0, width:SM_W, height:SM_H, fill:'rgba(255,255,255,.022)', rx:1}));
  const line = (x1,y1,x2,y2,st,w,dash) => { const l = svgEl('line',
    {x1,y1,x2,y2,stroke:st,'stroke-width':w||0.4}); if (dash) l.setAttribute('stroke-dasharray',dash);
    s.appendChild(l); };
  line(0, smy(25), SM_W, smy(25), 'rgba(90,150,220,.5)', 0.9);          // blue line
  line(0, smy(89), SM_W, smy(89), 'rgba(220,90,90,.55)', 0.6);          // goal line
  // faceoff dots, offensive zone
  [[69,-22],[69,22]].forEach(([fx,fy]) => {
    s.appendChild(svgEl('circle', {cx:smx(fy), cy:smy(fx), r:15, fill:'none',
      stroke:'rgba(220,90,90,.16)', 'stroke-width':0.35}));
    s.appendChild(svgEl('circle', {cx:smx(fy), cy:smy(fx), r:0.9, fill:'rgba(220,90,90,.35)'}));
  });
  // crease + net
  s.appendChild(svgEl('path', {d:`M ${smx(-4)} ${smy(89)} A 6 6 0 0 0 ${smx(4)} ${smy(89)}`,
    fill:'rgba(90,150,220,.10)', stroke:'rgba(90,150,220,.4)', 'stroke-width':0.3}));
  s.appendChild(svgEl('rect', {x:smx(-3), y:smy(89)-2.2, width:6, height:2.2,
    fill:'rgba(255,255,255,.10)', stroke:'rgba(255,255,255,.45)', 'stroke-width':0.35}));

  // ── density. one hue, light to dark: a sequential ramp, not a rainbow. ──
  grid.forEach(([gx, gy, n]) => {
    const rx = 25 + gx*5, ry = -42 + gy*5;
    const t = Math.pow(n / max, 0.6);                  // gamma so singles stay visible
    const r = svgEl('rect', {x:smx(ry), y:smy(rx+5), width:5, height:5,
      fill:GOAL_C, 'fill-opacity':(0.10 + t*0.72).toFixed(3), class:'cell'});
    r.addEventListener('mousemove', e => tipShow(e,
      `<b>${n} shot${n>1?'s':''}</b><br>${Math.round(Math.hypot(89-(rx+2.5), ry+2.5))} ft from the net<br>` +
      `<span style="opacity:.7">5-foot square</span>`));
    r.addEventListener('mouseleave', tipHide);
    s.appendChild(r);
  });

  // ── goals on top, sized by the chance quality the model gave them ──
  goals.forEach(([gx, gy, xg]) => {
    const rad = 0.9 + Math.sqrt(Math.max(xg,1)/100) * 3.4;
    // a goal scored on the goal line puts its marker half outside the rink box
    // and the circle gets sliced by the viewBox. Nudge the centre in by the
    // radius instead -- a unit and a half on a 75-unit rink is invisible, a
    // half-drawn circle is not.
    const clamp = (v, lo, hi) => Math.min(Math.max(v, lo), hi);
    const c = svgEl('circle', {cx:clamp(smx(gy), rad+0.3, SM_W-rad-0.3),
                               cy:clamp(smy(gx), rad+0.3, SM_H-rad-0.3), r:rad, fill:'none',
      stroke:'#fff', 'stroke-width':0.55, class:'goalmk'});
    c.addEventListener('mousemove', e => tipShow(e,
      `<b>Goal</b><br>${Math.round(Math.hypot(89-gx, gy))} ft out<br>` +
      `${xg}% chance by our model`));
    c.addEventListener('mouseleave', tipHide);
    s.appendChild(c);
  });
  host.appendChild(s);

  host.appendChild(el('div','legend',
    `<span><i style="background:${GOAL_C};opacity:.30"></i>Shot density, 5&#8209;foot squares</span>` +
    `<span><i class="ring"></i>Goal, sized by chance quality</span>`));

  const notes = [];
  notes.push(`${drawn} shots drawn, ${goals.length} of his ${career2025 ? career2025[2] : goals.length} goals.`);
  if (off || goalsOff) notes.push(
    `${off + goalsOff} taken from outside the offensive zone` +
    (goalsOff ? ` (including ${goalsOff} goal${goalsOff>1?'s':''})` : '') + '. Not drawn.');
  notes.push(`Densest square: ${max} shots.`);
  host.appendChild(el('div','cat', notes.join(' '))).setAttribute('style',
    'margin-top:10px;text-transform:none;letter-spacing:0;font-weight:400;font-size:11.5px');
}

function drawDash(){
  const p = P_BY[dashPid];
  const rows = (PD.career[String(dashPid)] || []).map(r => r.slice());
  const cur  = rows.find(r => r[0] === 2025);
  const med  = PD.leagueMedian2025[posGrp(p)];
  const proj = PR.find(x => x.name === p.n);

  // roster rail
  const rail = $('#dashRoster'); rail.innerHTML = '';
  PD.roster.forEach(r => {
    const b = el('button','ptab' + (r.id === dashPid ? ' on' : ''));
    b.setAttribute('aria-pressed', r.id === dashPid);
    b.innerHTML = `<span class="pnum">${r.num}</span><span class="pnm">${last(r.n)}</span><span class="ppos">${r.pos}</span>`;
    b.onclick = () => { dashPid = r.id; drawDash(); };
    rail.appendChild(b);
  });

  // header
  $('#dashHead').innerHTML =
    `<div class="phead">
       <div class="pjersey">${p.num}</div>
       <div class="pid">
         <h3>${p.n}</h3>
         <div class="pmeta">${p.pos} &middot; shoots ${p.sh} &middot; ${ft(p.ht)} &middot; ${p.wt} lb &middot; ${age(p.dob)} on opening night</div>
       </div>
     </div>
     <div class="heros">
       <div class="hero"><div class="lbl">2025-26 per game</div><div class="hv">${p.fp.toFixed(2)}</div>
         <div class="hs">fantasy points &middot; <b>${p.q.fp}th</b> of ${p.npos} ${posGrp(p)==='D'?'D':'F'}</div></div>
       <!-- NOT "projected tonight": the score bug at the top of every page says
            tonight is Anaheim at Toronto on 12 March. This is the Citrus
            Projections 2.0 number for opening night against Montreal, and it
            is the one place in the build where that roster still belongs. -->
       <div class="hero"><div class="lbl">Projected, opening night</div><div class="hv">${proj ? proj.mean.toFixed(2) : '-'}</div>
         <div class="hs">29 Sept vs Montreal &middot; ${proj ? proj.conf + ' confidence' : 'not dressing'}</div></div>
       <div class="hero"><div class="lbl">Shot quality</div><div class="hv">${p.xg60.toFixed(2)}</div>
         <div class="hs">xG per 60 &middot; <b>${p.xgr}</b></div></div>
     </div>`;

  // The finishing story, in words. Summing the last three seasons hides the
  // shape -- Matthews' 2023 (+24.1) swamps two negative years and reads as a
  // hot streak. Describe the actual RUN instead: how many seasons in a row on
  // the current side of expected, and what came before it.
  const tot = rows.reduce((s, r) => s + r[4], 0);
  const runOf = (arr) => { if (!arr.length) return [0, 0];
    const sign = arr[arr.length-1][4] >= 0 ? 1 : -1; let n = 0;
    for (let i = arr.length-1; i >= 0 && (arr[i][4] >= 0 ? 1 : -1) === sign; i--) n++;
    return [n, sign]; };
  const [run, sign] = runOf(rows);
  const prior = rows.slice(0, rows.length - run);
  const [prun, psign] = runOf(prior);
  const word = s => s > 0 ? 'above' : 'below';
  const yrs = n => n + (n === 1 ? ' season' : ' seasons');
  $('#finStory').innerHTML = !rows.length ? '' :
    `Across ${yrs(rows.length)} ${last(p.n)} has finished <b style="color:${tot>=0?GOAL_C:XG_C}">` +
    `${tot>=0?'+':''}${tot.toFixed(1)}</b> against what the chances were worth. ` +
    `The last ${yrs(run)} came in <b style="color:${sign>0?GOAL_C:XG_C}">${word(sign)}</b> expected` +
    (prun >= 2 ? `, after ${yrs(prun)} straight ${word(psign)} it` : '') + '. ' +
    `League median for a ${posGrp(p)==='D'?'defenceman':'forward'} last season was ` +
    `${med.finishing>=0?'+':''}${med.finishing.toFixed(2)}.`;

  chartShots($('#cShots'), dashPid, p, cur);
  chartGoals($('#cGoals'), rows, p.n);
  chartFin($('#cFin'), rows);
  chartRank($('#cRank'), p);
  chartForm($('#cForm'), dashPid, p);
  $('#formCap').textContent = PD.form[String(dashPid)]
    ? `Last ${PD.form[String(dashPid)].length} games of 2025-26, fantasy points by night.` : '';

  // shot profile against the league median for his position
  const prof = !cur ? [] : [
    ['Average shot',  cur[5],                  med.dist,        'ft', true],
    ['xG per shot',   cur[3]/cur[1]*100,       med.xgPerSogPct, '%',  false],
    ['Off the rush',  cur[6]/cur[1]*100,       med.rushPct,     '%',  false],
    ['Rebound shots', cur[7]/cur[1]*100,       med.rebPct,      '%',  false],
  ];
  $('#cProfile').innerHTML = !prof.length ? '<div class="empty">No 2025-26 shot data.</div>' :
    prof.map(([lab, v, m, u, lowerBetter]) => {
      const better = lowerBetter ? v < m : v > m;
      const d = v - m;
      return `<div class="prow"><span class="pl">${lab}</span>
        <span class="pv">${v.toFixed(u==='ft'?1:2)}<em>${u}</em></span>
        <span class="pm">median ${m.toFixed(u==='ft'?1:2)}${u}</span>
        <span class="pd ${better?'up':'dn'}">${d>=0?'+':''}${d.toFixed(u==='ft'?1:2)}</span></div>`;
    }).join('');
  $('#profCap').textContent = cur
    ? `Against the median ${posGrp(p)==='D'?'defenceman':'forward'} in 2025-26 (${posGrp(p)==='D'?190:405} skaters, minimum 40 shots on goal).` : '';

  // the column nobody prints
  const foPct = p.fot ? (p.fow / p.fot * 100).toFixed(1) + '%' : '-';
  $('#cGrind').innerHTML = [
    ['Faceoffs won', p.fot ? p.fow + ' of ' + p.fot : 'takes none', null],
    ['Faceoff %', foPct, null],
    ['Shot attempts', p.att, p.q.att],
    ['Attempts on goal', p.att ? (p.sog / p.att * 100).toFixed(1) + '%' : '-', null],
    ['Hits', p.hit, p.q.hit], ['Blocks', p.blk, p.q.blk], ['Takeaways', p.tk, p.q.tk],
    ['Giveaways', p.gv, null], ['Penalty minutes', p.pim, p.q.pim],
    ['Ice time', p.toi.toFixed(1) + ' min', p.q.toi], ['Shifts', p.shifts, null],
    ['Game winners', p.gwg, null],
  ].map(([lab, v, q]) =>
    `<div class="grow"><span class="gl">${lab}</span><span class="gv">${v}</span>` +
    `<span class="gq">${q==null ? '' : q + 'th'}</span></div>`).join('');

  $('#dashNums').innerHTML = dashTable ? dashNumbers(rows, p) : '';
  $('#numsBtn').textContent = dashTable ? 'Hide the numbers' : 'Show the numbers';
}

/* ══ WIRE UP ═════════════════════════════════════════════════════ */
$('#clGo').onclick = geoLock;
$('#shClose').onclick = closePicker;
$('#roomBtn').onclick = openRoom;
$('#rsClose').onclick = closeRoom;
$('#rsScrim').onclick = closeRoom;
$('#rsGo').onclick = () => {
  const h = ($('#rsHandle').value || '').trim().slice(0,18);
  if (!h){ $('#rsHandle').focus(); return; }
  ROOM.join(h.charAt(0) === '@' ? h : '@' + h, rsColour);
  if (ROOM.me) ROOM.score(CP, null, null);
  Snd.ding(); closeRoom();
};
$('#rsLeave').onclick = () => { ROOM.leave(); closeRoom(); };

$('#shScrim').onclick = closePicker;
$('#ultPerfect').onclick = () => { PARTS.forEach((P,i) => pick[P.id] = PERFECT.build[i]); ultOpen = null; drawParts(); tally(); };
$('#ultReset').onclick   = () => { Object.keys(pick).forEach(k => delete pick[k]); drawParts(); tally(); };
/* patched below */
$('#ultSubmit').onclick  = () => {
  const t = tally(); ultBanked = true;
  const perfect = Math.abs(t - PERFECT.total) < 0.005;
  if (perfect){ confetti(); Snd.win(); } else Snd.ding();
  award(Math.round(t / PERFECT.total * 300), 'Ultimate Leaf · '+t.toFixed(2)+' projected');
  LB_ULT.push({who:'You', build:PARTS.map(P => last(pick[P.id].name)).join(' / '), tot:t, you:true});
  if (typeof ROOM !== 'undefined' && ROOM.ok && ROOM.me){
    const b = {}; PARTS.forEach(P => b[P.id] = pick[P.id].name); ROOM.setUlt(b);
  }
  lbView = 'ult'; drawLB(); tally();
  // a delayed handoff must die the moment the fan navigates anywhere else
  window.__pendingGo = setTimeout(() => go('lb'), perfect && !CALM ? 700 : 0);
};
$('#stormyGo').onclick = stormyLock;
$('#stormyReset').onclick = () => { five = []; sLocked = false;
  const f = $('#sFinal'); if (f) f.remove(); $('#stormyVerdict').innerHTML = ''; drawStormy(); };
$('#numsBtn').onclick = () => { dashTable = !dashTable; drawDash(); };
$('#hlGo').onclick   = h2hLock;
$('#gMore').onclick  = () => { if(!gLock && gN<gClues.length){gN++; Snd.reveal(); gDraw();} };
$('#gHint').onclick  = gHint;
$('#gIn').addEventListener('input', e=>gSearch(e.target.value));
$('#gIn').addEventListener('keydown', e=>{ if(e.key==='Enter'){const b=$('#gList').querySelector('button'); if(b) b.click();} });
$('#lkGo').onclick   = heatLock;
$('#rkNext').onclick = rkNew;
$('#fxGo').onclick   = fxLock;
$('#bzStart').onclick= bzStart;
['cp','ult','stormy','room'].forEach(v => { const b=$('#lbTab_'+v); if (b) b.onclick = () => { lbView=v; drawLB(); }; });

