/* ── the clock's own controls ─────────────────────────────────── */
(function(){
  const leaf = $('#bugLeaf'); if (leaf) leaf.innerHTML = leafSVG(17, '#FFFFFF');
  const play = $('#bugPlay');
  if (play) play.onclick = () => {
    if (CLOCK.over){ const f = $('#clFinal'); if (f) f.remove(); CLOCK.reset(); clIdle(); }
    CLOCK.toggle();
  };
  const skip = $('#bugSkip'); if (skip) skip.onclick = () => { CLOCK.pause(); CLOCK.skip(); };
  const rst  = $('#bugReset');
  if (rst) rst.onclick = () => { const f = $('#clFinal'); if (f) f.remove(); CLOCK.reset(); clIdle(); };
  document.querySelectorAll('.ratebtn').forEach(b =>
    b.onclick = () => { CLOCK.set(+b.dataset.r); if (!CLOCK.running && !CLOCK.over) CLOCK.start(); });
  bugDraw();
})();

/* the club mark in front of every page title */
(function(){
  document.querySelectorAll('.ghero .hin').forEach(hin => {
    if (hin.querySelector('.clubmk')) return;
    const m = el('span','clubmk'); m.innerHTML = leafSVG(30, '#FFFFFF');
    hin.insertBefore(m, hin.firstChild);
  });
})();

/* the player page's four sections */
(function(){
  const segs = document.querySelectorAll('.segbar .seg');
  if (!segs.length) return;
  segs.forEach(s => s.onclick = () => {
    segs.forEach(o => { const on = o === s;
      o.classList.toggle('on', on); o.setAttribute('aria-selected', on); });
    document.querySelectorAll('.dsec').forEach(d =>
      d.classList.toggle('on', d.dataset.sec === s.dataset.sec));
    /* the charts size themselves off their container, and a container that
       was display:none measured zero, so redraw the one now on screen */
    if (typeof drawDash === 'function') drawDash();
  });
})();

ROOM.boot(); drawH2H(); gNew(); drawHeat(); rkNew(); drawFx(); drawLB(); drawCPLog(); drawDash(); igNew();
go(routeFromHash() || 'home', true);
